window.TEXTBOOK_TEXTS = Object.assign(window.TEXTBOOK_TEXTS || {}, {"hsk4b-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"李文和白家月在公园里散步聊天儿。","sceneVi":"Lý Văn và Bạch Gia Nguyệt vừa đi dạo vừa trò chuyện trong công viên.","lines":[{"speaker":"白家月","hanzi":"这里的老年人真不少。","pinyin":"Zhèlǐ de lǎoniánrén zhēn bùshǎo.","vi":"Người cao tuổi ở đây thật sự không ít chút nào."},{"speaker":"李文","hanzi":"嗯，住在附近的老年人都会来这儿，有的散步，有的唱歌、跳舞，还有的打太极拳。","pinyin":"Ǹg, zhù zài fùjìn de lǎoniánrén dōu huì lái zhèr, yǒude sànbù, yǒude chànggē, tiàowǔ, hái yǒude dǎ Tàijíquán.","vi":"Ừ, người cao tuổi sống quanh đây đều hay ra đây, người thì đi bộ, người thì ca hát, khiêu vũ, còn có người tập Thái Cực Quyền."},{"speaker":"白家月","hanzi":"他们的生活真丰富，让人羡慕。","pinyin":"Tāmen de shēnghuó zhēn fēngfù, ràng rén xiànmù.","vi":"Cuộc sống của họ thật phong phú, khiến người ta ngưỡng mộ quá."},{"speaker":"李文","hanzi":"是的。有些人即使年龄大了，也坚持去老年班学习。","pinyin":"Shì de. Yǒuxiē rén jíshǐ niánlíng dà le, yě jiānchí qù lǎoniánbān xuéxí.","vi":"Đúng thế. Có một số người dù tuổi đã cao nhưng vẫn kiên trì đến lớp học dành cho người cao tuổi."},{"speaker":"白家月","hanzi":"真是活到老学到老啊。","pinyin":"Zhēnshi huó dào lǎo xué dào lǎo a.","vi":"Đúng thật là sống đến già học đến già."},{"speaker":"李文","hanzi":"对，我爷爷就每周都去老年班学电脑。他总说，老年人也要继续学习，“你看，我都七八十岁了，还上网和网友们聊天儿呢，生活一点儿都不无聊。”","pinyin":"Duì, wǒ yéye jiù měizhōu dōu qù lǎoniánbān xué diànnǎo. Tā zǒng shuō, lǎoniánrén yě yào jìxù xuéxí, \"Nǐ kàn, wǒ dōu qībāshí suì le, hái shàngwǎng hé wǎngyǒumen liáotiānr ne, shēnghuó yìdiǎnr dōu bù wúliáo.\"","vi":"Đúng vậy, ông nội mình tuần nào cũng tới lớp người cao tuổi học máy tính. Ông luôn bảo người già cũng cần tiếp tục học tập: \"Cháu xem, ông bảy tám mươi tuổi rồi mà vẫn lên mạng tán gẫu với bạn bè trên mạng đấy, cuộc sống chẳng hề nhàm chán chút nào.\""}],"readingQuiz":[{"q":"白家月觉得公园里老年人的生活怎么样？","options":["很开心","很丰富","很辛苦","很无聊"],"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói \"他们的生活真丰富，让人羡慕。\" (Cuộc sống của họ thật phong phú, khiến người ta ngưỡng mộ)."},{"q":"李文的爷爷每周去老年班做什么？","options":["学电脑","学唱歌","学写字","学太极拳"],"answerIdx":0,"explanation":"Lý Văn cho biết \"我爷爷就每周都去老年班学电脑。\" (Ông nội mình tuần nào cũng đi lớp người cao tuổi học máy tính)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"在餐馆，李文请白家月、安妮一起吃饭。","sceneVi":"Tại nhà hàng, Lý Văn mời Bạch Gia Nguyệt và An Ni cùng ăn cơm.","lines":[{"speaker":"安妮","hanzi":"家月，我们今天的课是在数字教室上的，感觉挺不一样的。","pinyin":"Jiāyuè, wǒmen jīntiān de kè shì zài shùzì jiàoshì shàng de, gǎnjué tǐng bù yíyàng de.","vi":"Gia Nguyệt ơi, tiết học hôm nay của tụi mình học ở phòng học số, cảm giác khác hẳn luôn."},{"speaker":"白家月","hanzi":"是的，数字教室可以拍照点名，教授在线上点名，不用像线下那样一个个叫名字，特别节约时间。","pinyin":"Shì de, shùzì jiàoshì kěyǐ pāizhào diǎnmíng, jiàoshòu zài xiànshàng diǎnmíng, búyòng xiàng xiànxià nàyàng yígègè jiào míngzi, tèbié jiéyuē shíjiān.","vi":"Đúng vậy, phòng học số có thể chụp ảnh điểm danh, giáo sư điểm danh trực tuyến, không cần gọi từng tên một như học trực tiếp, rất tiết kiệm thời gian."},{"speaker":"李文","hanzi":"最方便的是，课上没听明白时，课后还能在学校网站上找到视频记录看。","pinyin":"Zuì fāngbiàn de shì, kèshàng méi tīng míngbai shí, kèhòu hái néng zài xuéxiào wǎngzhàn shàng zhǎodào shìpín jìlù kàn.","vi":"Tiện nhất là lúc trên lớp nghe chưa hiểu rõ, sau giờ học còn có thể tìm lại bản ghi video trên trang web của trường để xem."},{"speaker":"安妮","hanzi":"对，上课我都不用着急记笔记了。","pinyin":"Duì, shàngkè wǒ dōu búyòng zháojí jì bǐjì le.","vi":"Đúng thế, lúc học mình chẳng phải vội vàng chép ghi chú nữa."},{"speaker":"李文","hanzi":"不仅数字教室很方便，现在网上到处是学习资料，想查什么都能查到，自学也更方便了。","pinyin":"Bùjǐn shùzì jiàoshì hěn fāngbiàn, xiànzài wǎngshàng dàochù shì xuéxí zīliào, xiǎng chá shénme dōu néng chádào, zìxué yě gèng fāngbiàn le.","vi":"Không chỉ phòng học số tiện lợi, bây giờ trên mạng khắp nơi đều có tài liệu học tập, muốn tra gì cũng tìm được, tự học cũng thuận tiện hơn."},{"speaker":"白家月","hanzi":"是的，只要有手机或电脑，我就是不在教室，也可以学习中文，和同学一起练口语。","pinyin":"Shì de, zhǐyào yǒu shǒujī huò diànnǎo, wǒ jiùshì bú zài jiàoshì, yě kěyǐ xuéxí Zhōngwén, hé tóngxué yìqǐ liàn kǒuyǔ.","vi":"Đúng vậy, chỉ cần có điện thoại hoặc máy tính, cho dù không ở trong phòng học mình vẫn có thể học tiếng Trung và luyện khẩu ngữ cùng bạn học."},{"speaker":"安妮","hanzi":"科技真是让获取知识变得简单多了。","pinyin":"Kējì zhēnshi ràng huòqǔ zhīshi biànde jiǎndān duō le.","vi":"Công nghệ thực sự khiến việc tiếp thu kiến thức trở nên đơn giản hơn nhiều."}],"readingQuiz":[{"q":"白家月认为线上点名怎么样？","options":["节约时间","不太方便","比较随意","很吸引学生"],"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"教授在线上点名，不用像线下那样一个个叫名字，特别节约时间。\" (Giáo sư điểm danh online không cần gọi từng tên, đặc biệt tiết kiệm thời gian)."},{"q":"对安妮来说，线上上课时，自己不用急着做的事情是：","options":["写作业","找资料","记笔记","提问题"],"answerIdx":2,"explanation":"An Ni nói \"对，上课我都不用着急记笔记了。\" (Đúng, trên lớp mình chẳng phải vội vàng ghi chép nữa)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"周六，白家月和李文去王一雪家玩。回来后，白家月在家写日记。","sceneVi":"Thứ Bảy, Bạch Gia Nguyệt và Lý Văn sang nhà Vương Nhất Tuyết chơi. Về nhà, Bạch Gia Nguyệt viết nhật ký.","lines":[{"speaker":"Đoạn văn","hanzi":"今天星期六，我们去了一雪姐姐家。姐姐家的两个孩子很有礼貌，我们一进门，就马上和我们打招呼。","pinyin":"Jīntiān Xīngqīliù, wǒmen qù le Yīxuě jiějie jiā. Jiějie jiā de liǎng gè háizi hěn yǒu lǐmào, wǒmen yí jìnmén, jiù mǎshàng hé wǒmen dǎ zhāohu.","vi":"Hôm nay thứ Bảy, chúng tôi đến nhà chị Nhất Tuyết. Hai đứa nhỏ nhà chị rất lễ phép, chúng tôi vừa bước vào cửa là các bé liền chào hỏi ngay."},{"speaker":"Đoạn văn","hanzi":"在姐姐家，我们也聊到了孩子的教育。姐姐说，以前他们和很多家长一样，觉得孩子上个好大学，人生才是成功的。","pinyin":"Zài jiějie jiā, wǒmen yě liáodào le háizi de jiàoyù. Jiějie shuō, yǐqián tāmen hé hěnduō jiāzhǎng yíyàng, juéde háizi shàng gè hǎo dàxué, rénshēng cái shì chénggōng de.","vi":"Ở nhà chị, chúng tôi cũng trò chuyện về chuyện giáo dục con cái. Chị kể trước đây anh chị giống nhiều phụ huynh khác, cho rằng con đỗ đại học tốt thì cuộc đời mới gọi là thành công."},{"speaker":"Đoạn văn","hanzi":"所以，他们只关心孩子的分数，结果孩子压力特别大，每天都很不开心。","pinyin":"Suǒyǐ, tāmen zhǐ guānxīn háizi de fēnshù, jiéguǒ háizi yālì tèbié dà, měitiān dōu hěn bù kāixīn.","vi":"Vì vậy, họ chỉ quan tâm đến điểm số của con, kết quả là con cái áp lực vô cùng lớn, ngày nào cũng không vui."},{"speaker":"Đoạn văn","hanzi":"后来，他们认识到，教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","pinyin":"Hòulái, tāmen rènshi dào, jiàoyù de mùdì bú shì ràng háizi kǎo gāofēn, ér shì bāngzhù háizi yǎngchéng hǎo xíguàn.","vi":"Sau này, anh chị nhận ra mục đích của giáo dục không phải là bắt con thi điểm cao, mà là giúp con hình thành thói quen tốt."},{"speaker":"Đoạn văn","hanzi":"于是，他们做出改变，每天都给孩子留出时间外出锻炼身体，或者看些自己感兴趣的书。我觉得他们的做法真棒。","pinyin":"Yúshì, tāmen zuòchū gǎibiàn, měitiān dōu gěi háizi liúchū shíjiān wàichū duànliàn shēntǐ, huòzhě kàn xiē zìjǐ gǎn xìngqù de shū. Wǒ juéde tāmen de zuòfǎ zhēn bàng.","vi":"Thế là họ thay đổi, mỗi ngày đều dành thời gian cho con ra ngoài rèn luyện thân thể hoặc đọc những cuốn sách mình hứng thú. Tôi thấy cách làm của họ thật tuyệt vời."}],"readingQuiz":[{"q":"以前，王一雪和刘明认为孩子的人生怎样才是成功的？","options":["变得有名","有很多钱","上个好大学","有个好工作"],"answerIdx":2,"explanation":"Trong bài có câu \"以前他们和很多家长一样，觉得孩子上个好大学，人生才是成功的。\" (Trước đây họ cũng giống nhiều phụ huynh, cho rằng con vào được trường đại học tốt mới là thành công)."},{"q":"后来，王一雪和刘明认为教育是为了让孩子：","options":["获得高分","按时做作业","有个好身体","养成好习惯"],"answerIdx":3,"explanation":"Trong bài viết \"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。\" (Mục đích của giáo dục không phải thi điểm cao mà là giúp con hình thành thói quen tốt)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"学习，让生活更有意义","sceneVi":"Học tập giúp cuộc sống thêm ý nghĩa","lines":[{"speaker":"Đoạn văn","hanzi":"“学而不厌”是两千多年前中国教育家孔子说过的话，意思是人要一直坚持学习，就是说，学习是人一生的事情，要活到老学到老。","pinyin":"\"Xué ér bú yàn\" shì liǎngqiān duō nián qián Zhōngguó jiàoyùjiā Kǒngzǐ shuō guo de huà, yìsi shì rén yào yìzhí jiānchí xuéxí, jiùshì shuō, xuéxí shì rén yìshēng de shìqing, yào huó dào lǎo xué dào lǎo.","vi":"\"Học nhi bất yếm\" là câu nói của nhà giáo dục Trung Quốc Khổng Tử hơn hai nghìn năm trước, ý là con người cần kiên trì học mãi, nghĩa là việc học là chuyện cả đời, phải sống đến già học đến già."},{"speaker":"Đoạn văn","hanzi":"在世界快速变化的今天，“学而不厌”变得更加重要。","pinyin":"Zài shìjiè kuàisù biànhuà de jīntiān, \"xué ér bú yàn\" biànde gèngjiā zhòngyào.","vi":"Trong thời đại thế giới biến đổi nhanh chóng ngày nay, tinh thần \"học không biết chán\" càng trở nên quan trọng hơn."},{"speaker":"Đoạn văn","hanzi":"我有一位很优秀的律师朋友，他一直在学习新的法律知识。他说，这不仅是律师的要求和责任，也是提高自己能力的重要方法。","pinyin":"Wǒ yǒu yí wèi hěn yōuxiù de lǜshī péngyou, tā yìzhí zài xuéxí xīn de fǎlǜ zhīshi. Tā shuō, zhè bùjǐn shì lǜshī de yāoqiú hé zérèn, yě shì tígāo zìjǐ nénglì de zhòngyào fāngfǎ.","vi":"Tôi có một người bạn luật sư rất xuất sắc, anh ấy luôn học hỏi kiến thức pháp luật mới. Anh ấy bảo đó không chỉ là yêu cầu và trách nhiệm của luật sư mà còn là phương pháp quan trọng để nâng cao năng lực."},{"speaker":"Đoạn văn","hanzi":"同时我也认为，人就是不再工作了，坚持学习仍很重要。","pinyin":"Tóngshí wǒ yě rènwéi, rén jiùshì bú zài gōngzuò le, jiānchí xuéxí réng hěn zhòngyào.","vi":"Đồng thời tôi cũng cho rằng con người dù không còn đi làm nữa thì việc kiên trì học tập vẫn rất quan trọng."},{"speaker":"Đoạn văn","hanzi":"就像我爷爷，虽然七十多岁了，每天还准时去老年大学上课，学习做网页、弹钢琴。他说，重新当一回学生，生活更有意思了，也感觉自己变年轻了。","pinyin":"Jiù xiàng wǒ yéye, suīrán qīshí duō suì le, měitiān hái zhǔnshí qù lǎonián dàxué shàngkè, xuéxí zuò wǎngyè, tán gāngqín. Tā shuō, chóngxīn dāng yì huí xuésheng, shēnghuó gèng yǒuyìsi le, yě gǎnjué zìjǐ biàn niánqīng le.","vi":"Cũng như ông nội tôi, tuy đã ngoài bảy mươi nhưng ngày nào cũng đúng giờ đến trường đại học người cao tuổi học làm trang web, đánh đàn piano. Ông nói được làm học sinh lại một lần nữa khiến cuộc sống thú vị hơn và cảm thấy mình trẻ ra."}],"readingQuiz":[{"q":"“学而不厌”是孔子什么时候说的？","options":["二十多年前","两百多年前","两千多年前","五千多年前"],"answerIdx":2,"explanation":"Đoạn văn nêu rõ \"“学而不厌”是两千多年前中国教育家孔子说过的话\" (Là lời nhà giáo dục Khổng Tử nói hơn hai nghìn năm trước)."},{"q":"坚持学习，爷爷觉得怎么样？","options":["很开心","有点儿累","更健康了","年轻起来了"],"answerIdx":3,"explanation":"Cuối bài ông nội nói \"生活更有意思了，也感觉自己变年轻了。\" (Cuộc sống thú vị hơn và cảm thấy mình trẻ lại)."}]}],"hsk4b-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"在商场，杨同乐和王一飞在给父母买衣服。","sceneVi":"Tại trung tâm thương mại, Dương Đồng Nhạc và Vương Nhất Phi đang mua quần áo cho bố mẹ.","lines":[{"speaker":"王一飞","hanzi":"你觉得老妈穿这件毛衣怎么样？","pinyin":"Nǐ juéde lǎomā chuān zhè jiàn máoyī zěnmeyàng?","vi":"Anh thấy mẹ mặc chiếc áo len này thế nào?"},{"speaker":"杨同乐","hanzi":"样子不错，就是颜色好像不怎么适合她。","pinyin":"Yàngzi búcuò, jiùshì yánsè hǎoxiàng bù zěnme shìhé tā.","vi":"Kiểu dáng đẹp đấy, chỉ là màu sắc có vẻ không hợp với mẹ lắm."},{"speaker":"售货员","hanzi":"老年人穿这种颜色的衣服正合适，颜色不深，质量还特别好。您看那位阿姨正试着呢，是不是很好看？","pinyin":"Lǎoniánrén chuān zhè zhǒng yánsè de yīfu zhèng héshì, yánsè bù shēn, zhìliàng hái tèbié hǎo. Nín kàn nà wèi āyí zhèng shìzhe ne, shìbushì hěn hǎokàn?","vi":"Người lớn tuổi mặc màu này rất hợp ạ, màu không quá đậm, chất lượng lại cực kỳ tốt. Anh chị nhìn bác gái kia đang mặc thử kìa, có phải rất đẹp không?"},{"speaker":"王一飞","hanzi":"嗯，是挺不错的。同乐，我印象中，老妈也常穿这种颜色的衣服，她应该会喜欢的，买一件吧。","pinyin":"Ǹg, shì tǐng búcuò de. Tónglè, wǒ yìnxiàng zhōng, lǎomā yě cháng chuān zhè zhǒng yánsè de yīfu, tā yīnggāi huì xǐhuan de, mǎi yí jiàn ba.","vi":"Ừm, đúng là khá đẹp đấy. Đồng Nhạc, trong ấn tượng của em mẹ cũng hay mặc quần áo màu này, chắc chắn mẹ sẽ thích, mua một chiếc đi."},{"speaker":"杨同乐","hanzi":"好的，老妈高兴比什么都强。","pinyin":"Hǎo de, lǎomā gāoxìng bǐ shénme dōu qiáng.","vi":"Được thôi, mẹ vui là hơn tất cả."},{"speaker":"售货员","hanzi":"就是，老人开心最重要。我们店正好年底有活动，全场打七折呢，挺值的。","pinyin":"Jiùshì, lǎorén kāixīn zuì zhòngyào. Wǒmen diàn zhènghǎo niándǐ yǒu huódòng, quánchǎng dǎ qīzhé ne, tǐng zhí de.","vi":"Đúng vậy ạ, người lớn tuổi vui là quan trọng nhất. Cửa hàng chúng tôi đúng dịp cuối năm đang có khuyến mãi giảm 30% toàn bộ cửa hàng đấy, rất đáng mua."}],"readingQuiz":[{"q":"杨同乐认为毛衣的颜色怎么样？","options":["很合适","不合适","正流行","太深了"],"answerIdx":1,"explanation":"Lúc đầu Dương Đồng Nhạc nói \"样子不错，就是颜色好像不怎么适合她。\" (Kiểu dáng ổn nhưng màu sắc hình như không hợp với mẹ lắm)."},{"q":"商场年底有什么活动？","options":["买一送一","买二送一","全场七折","免费送货"],"answerIdx":2,"explanation":"Nhân viên bán hàng nói \"我们店正好年底有活动，全场打七折呢，挺值的。\" (Cuối năm cửa hàng có ưu đãi giảm giá còn 70% / giảm 30% toàn bộ cửa hàng)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"刘明下班回到家中，和王一雪聊天儿。","sceneVi":"Lưu Minh tan làm về đến nhà, trò chuyện với Vương Nhất Tuyết.","lines":[{"speaker":"刘明","hanzi":"爷爷、奶奶还没回来呢？","pinyin":"Yéye, nǎinai hái méi huílái ne?","vi":"Ông nội, bà nội vẫn chưa về à em?"},{"speaker":"王一雪","hanzi":"没呢，估计快了。下午老年班举办一期听力保护活动，他们去参加活动了。","pinyin":"Méi ne, gūjì kuài le. Xiàwǔ lǎoniánbān jǔbàn yì qī tīnglì bǎohù huódòng, tāmen qù cānjiā huódòng le.","vi":"Chưa anh, chắc sắp về rồi. Chiều nay lớp người cao tuổi tổ chức một buổi hoạt động bảo vệ thính lực, ông bà đi tham gia rồi."},{"speaker":"刘明","hanzi":"他们的活动还挺丰富的！","pinyin":"Tāmen de huódòng hái tǐng fēngfù de!","vi":"Hoạt động của ông bà phong phú thật đấy!"},{"speaker":"王一雪","hanzi":"嗯。小明最近要考试，心里有点儿烦，昨天因为脱、挂衣服这点儿小事，就对奶奶发脾气了。","pinyin":"Ǹg. Xiǎomíng zuìjìn yào kǎoshì, xīnlǐ yǒudiǎnr fán, zuótiān yīnwèi tuō, guà yīfu zhè diǎnr xiǎoshì, jiù duì nǎinai fā píqi le.","vi":"Ừ. Tiểu Minh dạo này sắp thi nên trong lòng hơi bứt rứt, hôm qua chỉ vì chuyện nhỏ như cởi và treo quần áo mà nổi nóng với bà nội."},{"speaker":"刘明","hanzi":"是吗？他这样做老人该伤心了。","pinyin":"Shì ma? Tā zhèyàng zuò lǎorén gāi shāngxīn le.","vi":"Thật sao? Thằng bé làm thế ông bà buồn lắm đấy."},{"speaker":"王一雪","hanzi":"就是啊。他也不是不知道自己错了，我批评他以后，他马上说放学回来就向奶奶道歉。","pinyin":"Jiùshì a. Tā yě bú shì bù zhīdào zìjǐ cuò le, wǒ pīpíng tā yǐhòu, tā mǎshàng shuō fàngxué huílái jiù xiàng nǎinai dàoqiàn.","vi":"Đúng vậy. Không phải con không biết mình sai đâu, sau khi em phê bình thì nó liền bảo tan học về sẽ xin lỗi bà ngay."},{"speaker":"刘明","hanzi":"好的，我也再跟他聊聊。","pinyin":"Hǎo de, wǒ yě zài gēn tā liáoliao.","vi":"Được, để anh cũng nói chuyện thêm với con."},{"speaker":"王一雪","hanzi":"那就更好了。","pinyin":"Nà jiù gèng hǎo le.","vi":"Thế thì càng tốt hơn."}],"readingQuiz":[{"q":"爷爷、奶奶下午去做什么了？","options":["打扫卫生","在家睡觉","接小明放学","参加老年班活动"],"answerIdx":3,"explanation":"Vương Nhất Tuyết nói \"下午老年班举办一期听力保护活动，他们去参加活动了。\" (Chiều nay lớp người cao tuổi tổ chức hoạt động bảo vệ thính lực, ông bà đi tham gia rồi)."},{"q":"王一雪批评小明，是因为他：","options":["总是迟到","不打扫房间","对奶奶发脾气","考试前不复习"],"answerIdx":2,"explanation":"Trong bài nêu \"昨天因为脱、挂衣服这点儿小事，就对奶奶发脾气了。\" (Hôm qua vì chuyện nhỏ mà nổi nóng với bà nội)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"为幸福而努力","sceneVi":"Nỗ lực vì hạnh phúc","lines":[{"speaker":"Đoạn văn","hanzi":"杨同乐的老家在上海，他自毕业后一直在北京工作。虽然没和父母生活在一起，但父子、母子关系特别好。","pinyin":"Yáng Tónglè de lǎojiā zài Shànghǎi, tā zì bìyè hòu yìzhí zài Běijīng gōngzuò. Suīrán méi hé fùmǔ shēnghuó zài yìqǐ, dàn fùzǐ, mǔzǐ guānxi tèbié hǎo.","vi":"Quê của Dương Đồng Nhạc ở Thượng Hải, từ sau khi tốt nghiệp anh ấy luôn làm việc tại Bắc Kinh. Tuy không sống chung với bố mẹ nhưng tình cảm cha con, mẹ con đặc biệt gắn bó."},{"speaker":"Đoạn văn","hanzi":"杨同乐很关心父母，无论平时工作有多忙，他每个周末都会给父母打电话。条件允许时，他会回上海看父母。","pinyin":"Yáng Tónglè hěn guānxīn fùmǔ, wúlùn píngshí gōngzuò yǒu duō máng, tā měi gè zhōumò dōu huì gěi fùmǔ dǎ diànhuà. Tiáojiàn yǔnxǔ shí, tā huì huí Shànghǎi kàn fùmǔ.","vi":"Dương Đồng Nhạc rất quan tâm bố mẹ, bất kể ngày thường công việc bận đến đâu cuối tuần nào anh cũng gọi điện về cho bố mẹ. Khi điều kiện cho phép, anh sẽ về Thượng Hải thăm ông bà."},{"speaker":"Đoạn văn","hanzi":"刘明和王一雪结婚后，一直没有和父母生活在一起，他们平时会另外找时间去看父母，帮父母做做饭，打扫打扫卫生。","pinyin":"Liú Míng hé Wáng Yīxuě jiéhūn hòu, yìzhí méiyǒu hé fùmǔ shēnghuó zài yìqǐ, tāmen píngshí huì lìngwài zhǎo shíjiān qù kàn fùmǔ, bāng fùmǔ zuòzuo fàn, dǎsǎo dǎsǎo wèishēng.","vi":"Sau khi Lưu Minh và Vương Nhất Tuyết kết hôn, họ luôn không ở chung với bố mẹ, ngày thường hai vợ chồng dành thêm thời gian sang thăm, giúp bố mẹ nấu cơm và dọn dẹp nhà cửa."},{"speaker":"Đoạn văn","hanzi":"这两年，刘明的母亲身体不太好，他们很担心，就把父母接到了自己家里照顾。父母待在他们身边，他们也终于能放心地去工作了。","pinyin":"Zhè liǎng nián, Liú Míng de mǔqīn shēntǐ bú tài hǎo, tāmen hěn dānxīn, jiù bǎ fùmǔ jiēdào le zìjǐ jiālǐ zhàogù. Fùmǔ dāi zài tāmen shēnbiān, tāmen yě zhōngyú néng fàngxīn de qù gōngzuò le.","vi":"Hai năm nay sức khỏe mẹ của Lưu Minh không được tốt, họ rất lo lắng nên đã đón bố mẹ về nhà mình chăm sóc. Có bố mẹ ở bên cạnh, hai người cuối cùng cũng yên tâm đi làm."}],"readingQuiz":[{"q":"杨同乐每个周末都会做什么？","options":["回上海","去北京出差","带父母旅游","给父母打电话"],"answerIdx":3,"explanation":"Trong bài viết \"无论平时工作有多忙，他每个周末都会给父母打电话。\" (Bất kể công việc bận đến đâu, cuối tuần nào anh cũng gọi điện cho bố mẹ)."},{"q":"刘明的母亲身体变差后，刘明和王一雪：","options":["不再工作了","请别人帮忙照顾","带父母回了老家","把父母接到了自己家"],"answerIdx":3,"explanation":"Đoạn văn nêu rõ \"就把父母接到了自己家里照顾。\" (Đã đón bố mẹ về nhà mình chăm sóc)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"幸福的味道","sceneVi":"Hương vị của hạnh phúc","lines":[{"speaker":"Đoạn văn","hanzi":"下班回家，林静静将父母从老家寄来的鸡汤热了热，当闻到从小就熟悉的味道时，平时冷静的她鼻子还是酸了。","pinyin":"Xiàbān huíjiā, Lín Jìngjing jiāng fùmǔ cóng lǎojiā jìlái de jītāng rè le rè, dāng wéndào cóngxiǎo jiù shúxi de wèidào shí, píngshí lěngjìng de tā bízi háishi suān le.","vi":"Tan làm về nhà, Lâm Tĩnh Tĩnh hâm nóng lại món canh gà bố mẹ gửi từ quê lên; khi ngửi thấy mùi vị quen thuộc từ nhỏ, cô gái vốn bình tĩnh là thế cũng thấy cay cay sống mũi."},{"speaker":"Đoạn văn","hanzi":"林静静一个人来北京工作三年了，父母总是担心她为了节约时间而不好好吃饭，所以每个月都给她寄各种好吃的。","pinyin":"Lín Jìngjing yígèrén lái Běijīng gōngzuò sān nián le, fùmǔ zǒngshì dānxīn tā wèile jiéyuē shíjiān ér bù hǎohāo chīfàn, suǒyǐ měigè yuè dōu gěi tā jì gèzhǒng hǎochī de.","vi":"Lâm Tĩnh Tĩnh một mình đến Bắc Kinh làm việc đã ba năm, bố mẹ luôn lo con gái vì tiết kiệm thời gian mà ăn uống qua loa, nên tháng nào cũng gửi cho cô đủ thứ đồ ăn ngon."},{"speaker":"Đoạn văn","hanzi":"这次母亲专门做了林静静最爱喝的鸡汤，为了让食物新鲜，父亲选择了城里最快的快递，上午寄出，下午就能收到。","pinyin":"Zhè cì mǔqīn zhuānmén zuò le Lín Jìngjing zuì ài hē de jītāng, wèile ràng shíwù xīnxiān, fùqīn xuǎnzé le chénglǐ zuì kuài de kuàidì, shàngwǔ jìchū, xiàwǔ jiù néng shōudào.","vi":"Lần này mẹ đích thân nấu món canh gà mà Tĩnh Tĩnh thích uống nhất, để đồ ăn giữ được độ tươi, bố chọn dịch vụ chuyển phát nhanh nhất trong thành phố, sáng gửi chiều đã nhận được."},{"speaker":"Đoạn văn","hanzi":"鸡汤很鲜，林静静心里更暖，她觉得父母好像就在身边。","pinyin":"Jītāng hěn xiān, Lín Jìngjing xīnlǐ gèng nuǎn, tā juéde fùmǔ hǎoxiàng jiù zài shēnbiān.","vi":"Canh gà rất ngọt ngon, lòng Lâm Tĩnh Tĩnh lại càng ấm áp, cô cảm thấy bố mẹ dường như đang ở ngay bên cạnh."},{"speaker":"Đoạn văn","hanzi":"都说“儿行千里母担忧”，父母总对她说：“遇到困难别害怕，要勇敢面对，任何时候都可以和父母商量。”尽管在大城市生活压力有些大，但每当想到父母的这些话，尝到来自老家熟悉的味道，她就觉得又能笑着面对生活了。","pinyin":"Dōu shuō \"Ér xíng qiānlǐ mǔ dānyōu\", fùmǔ zǒng duì tā shuō: \"Yùdào kùnnan bié hàipà, yào yǒnggǎn miànduì, rènhé shíhou dōu kěyǐ hé fùmǔ shāngliang.\" Jǐnguǎn zài dà chéngshì shēnghuó yālì yǒuxiē dà, dàn měidāng xiǎngdào fùmǔ de zhèxiē huà, chángdào láizì lǎojiā shúxi de wèidào, tā jiù juéde yòu néng xiàozhe miànduì shēnghuó le.","vi":"Người ta vẫn nói \"Con đi ngàn dặm mẹ lo lắng\", bố mẹ luôn dặn cô: \"Gặp khó khăn đừng sợ, phải dũng cảm đối mặt, bất cứ lúc nào cũng có thể bàn bạc với bố mẹ.\" Dù áp lực sống ở thành phố lớn có hơi nặng, nhưng mỗi khi nhớ đến những lời ấy và nếm hương vị quen thuộc từ quê nhà, cô lại thấy mình có thể mỉm cười đối diện cuộc sống."}],"readingQuiz":[{"q":"林静静下班回家后热的是：","options":["奶茶","鸡汤","包子","米饭"],"answerIdx":1,"explanation":"Câu mở đầu viết \"林静静将父母从老家寄来的鸡汤热了热\" (Lâm Tĩnh Tĩnh hâm nóng lại canh gà bố mẹ gửi từ quê lên)."},{"q":"父母给林静静寄了什么？","options":["好用的","好吃的","好玩的","好看的"],"answerIdx":1,"explanation":"Trong bài viết \"所以每个月都给她寄各种好吃的\" (Tháng nào cũng gửi cho cô đủ loại đồ ăn ngon)."}]}],"hsk4b-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"六一儿童节，刘明、王一雪带刘小明到北京野生动物园看动物，他们先坐车进入猛兽区。","sceneVi":"Ngày Quốc tế Thiếu nhi 1/6, Lưu Minh và Vương Nhất Tuyết đưa Lưu Tiểu Minh đi Công viên Động vật hoang dã Bắc Kinh, trước tiên họ ngồi xe vào khu thú dữ.","lines":[{"speaker":"刘小明","hanzi":"爸爸、妈妈，快看，熊和老虎都在这儿呢！","pinyin":"Bàba, māma, kuài kàn, xióng hé lǎohǔ dōu zài zhèr ne!","vi":"Bố mẹ ơi nhìn nhanh kìa, gấu và hổ đều ở đây này!"},{"speaker":"王一雪","hanzi":"小明，注意安全，不要一直大喊！","pinyin":"Xiǎomíng, zhùyì ānquán, búyào yìzhí dàhǎn!","vi":"Tiểu Minh, chú ý an toàn, đừng hét to mãi thế!"},{"speaker":"刘明","hanzi":"你们看，那个叫东北虎，是国家一级保护动物。那边树林里还有很多动物呢。","pinyin":"Nǐmen kàn, nàge jiào Dōngběihǔ, shì guójiā yī jí bǎohù dòngwù. Nàbiān shùlín lǐ hái yǒu hěnduō dòngwù ne.","vi":"Hai mẹ con nhìn kìa, con kia gọi là hổ Đông Bắc, là động vật bảo vệ cấp một quốc gia. Trong rừng cây bên kia còn nhiều động vật lắm."},{"speaker":"刘小明","hanzi":"咱们都能看到吧？","pinyin":"Zánmen dōu néng kàndào ba?","vi":"Nhà mình đều xem được hết chứ ạ?"},{"speaker":"王一雪","hanzi":"对。景区的车每到一个动物区都会停一会儿，让人们能近距离看看这些动物。","pinyin":"Duì. Jǐngqū de chē měi dào yígè dòngwù qū dōu huì tíng yíhuìr, ràng rénmen néng jìn jùlí kànkan zhèxiē dòngwù.","vi":"Đúng vậy. Xe của khu tham quan cứ đến mỗi khu động vật sẽ dừng lại một lát để mọi người được ngắm chúng ở cự ly gần."},{"speaker":"刘明","hanzi":"真不错，这景区真大、真美！我知道北京野生动物园很大，可怎么也没想到这么大！","pinyin":"Zhēn búcuò, zhè jǐngqū zhēn dà, zhēn měi! Wǒ zhīdào Běijīng Yěshēng Dòngwùyuán hěn dà, kě zěnme yě méi xiǎngdào zhème dà!","vi":"Tuyệt thật, khu tham quan này vừa rộng vừa đẹp! Anh biết Công viên Động vật hoang dã Bắc Kinh rộng, nhưng không thể ngờ lại rộng thế này!"},{"speaker":"王一雪","hanzi":"这里有几千只动物呢，能不大吗？现在是节假日，人多。小明，一会儿千万别跑丢了，我可不是开玩笑呢。","pinyin":"Zhèlǐ yǒu jǐqiān zhī dòngwù ne, néng bú dà ma? Xiànzài shì jiéjiàrì, rén duō. Xiǎomíng, yíhuìr qiānwàn bié pǎodiū le, wǒ kě bú shì kāiwánxiào ne.","vi":"Ở đây có mấy nghìn con thú mà, sao không rộng được chứ? Nay là ngày lễ nên đông người. Tiểu Minh, lát nữa tuyệt đối đừng chạy lạc đấy, mẹ không đùa đâu."}],"readingQuiz":[{"q":"王一雪提醒小明：","options":["别害怕","不要吃东西","看看熊和老虎","不要总是大喊"],"answerIdx":3,"explanation":"Vương Nhất Tuyết nhắc con \"小明，注意安全，不要一直大喊！\" (Tiểu Minh, chú ý an toàn, đừng hét to mãi thế!)."},{"q":"刘明觉得景区怎么样？","options":["游客很多","门票便宜","又大又美","饭馆很多"],"answerIdx":2,"explanation":"Lưu Minh khen \"这景区真大、真美！\" (Khu tham quan này thật rộng, thật đẹp!)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"在王一飞家，王一飞夫妇邀请白家月、安妮和陈天中过中秋节。","sceneVi":"Tại nhà Vương Nhất Phi, vợ chồng Vương Nhất Phi mời Bạch Gia Nguyệt, An Ni và Trần Thiên Trung đón Tết Trung Thu.","lines":[{"speaker":"王一飞","hanzi":"来，大家快吃月饼，这儿还有葡萄、西瓜。","pinyin":"Lái, dàjiā kuài chī yuèbǐng, zhèr hái yǒu pútao, xīguā.","vi":"Nào, mọi người ăn bánh trung thu đi, ở đây còn có nho và dưa hấu nữa."},{"speaker":"杨同乐","hanzi":"这是今年的新茶，你们也尝尝。","pinyin":"Zhè shì jīnnián de xīnchá, nǐmen yě chángchang.","vi":"Đây là trà mới năm nay, các bạn cũng nếm thử đi."},{"speaker":"陈天中","hanzi":"好的。这茶闻着真香！","pinyin":"Hǎo de. Zhè chá wénzhe zhēn xiāng!","vi":"Vâng ạ. Trà này ngửi thơm thật đấy!"},{"speaker":"白家月","hanzi":"我还是第一次在中国过中秋节呢。","pinyin":"Wǒ háishi dì yī cì zài Zhōngguó guò Zhōngqiūjié ne.","vi":"Mình vẫn là lần đầu tiên đón Tết Trung Thu ở Trung Quốc đấy."},{"speaker":"安妮","hanzi":"我在加拿大时和中国朋友一起过过中秋节。我记得那天，外面的街道、剧院有很多演出活动。","pinyin":"Wǒ zài Jiānádà shí hé Zhōngguó péngyou yìqǐ guò guo Zhōngqiūjié. Wǒ jìde nàtiān, wàimiàn de jiēdào, jùyuàn yǒu hěnduō yǎnchū huódòng.","vi":"Lúc ở Canada mình từng đón Trung Thu cùng bạn Trung Quốc rồi. Mình nhớ hôm đó đường phố và nhà hát bên ngoài có nhiều hoạt động biểu diễn lắm."},{"speaker":"王一飞","hanzi":"在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。对了，家月，今天是李文爷爷的生日，李文来不了了，你就多吃一块月饼吧。","pinyin":"Zài Zhōngguó, měinián Zhōngqiūjié dōu huì jǔbàn hěnduō huódòng, érqiě zhè jǐ nián yì nián bǐ yì nián rènao. Duìle, Jiāyuè, jīntiān shì Lǐ Wén yéye de shēngrì, Lǐ Wén lái bu liǎo le, nǐ jiù duō chī yí kuài yuèbǐng ba.","vi":"Ở Trung Quốc, mỗi năm dịp Trung Thu đều tổ chức nhiều hoạt động, hơn nữa mấy năm nay năm sau lại náo nhiệt hơn năm trước. À Gia Nguyệt, hôm nay là sinh nhật ông nội Lý Văn nên Lý Văn không tới được, bạn ăn thêm một miếng bánh trung thu nhé."},{"speaker":"白家月","hanzi":"谢谢，那我就不客气了。","pinyin":"Xièxie, nà wǒ jiù bú kèqi le.","vi":"Cảm ơn chị, thế em xin phép không khách sáo nữa."},{"speaker":"杨同乐","hanzi":"中秋节和生日赶在了一块儿，真巧、真好！中秋节多陪陪家人也是应该的。","pinyin":"Zhōngqiūjié hé shēngrì gǎnzài le yíkuàir, zhēn qiǎo, zhēn hǎo! Zhōngqiūjié duō péipei jiārén yě shì yīnggāi de.","vi":"Trung Thu và sinh nhật trùng vào một ngày, thật khéo và thật vui! Dịp Trung Thu ở bên gia đình nhiều hơn cũng là điều nên làm."}],"readingQuiz":[{"q":"王一飞和杨同乐准备了什么？","options":["月饼、葡萄和苹果","葡萄、西瓜和苹果","月饼、苹果、西瓜和茶","月饼、葡萄、西瓜和茶"],"answerIdx":3,"explanation":"Vương Nhất Phi mời ăn \"月饼、葡萄、西瓜\" và Dương Đồng Nhạc mời thêm \"今年的新茶\"."},{"q":"李文为什么没来？","options":["在学校学习","去买水果了","要给爷爷过生日","和同事一起过节"],"answerIdx":2,"explanation":"Trong bài nói \"今天是李文爷爷的生日，李文来不了了\" (Hôm nay là sinh nhật ông nội Lý Văn nên Lý Văn không đến được)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"中秋节的“反向团圆”","sceneVi":"Cuộc \"đoàn viên ngược chiều\" dịp Tết Trung Thu","lines":[{"speaker":"Đoạn văn","hanzi":"中秋节时中国人一般都会回家过节。但是有些人由于工作需要，不能回家，只能一个人留在工作的地方过节。周力就是这些人之中的一位。","pinyin":"Zhōngqiūjié shí Zhōngguórén yìbān dōu huì huíjiā guòjié. Dànshì yǒuxiē rén yóuyú gōngzuò xūyào, bùnéng huíjiā, zhǐnéng yígèrén liúzài gōngzuò de dìfang guòjié. Zhōu Lì jiùshì zhèxiē rén zhīzhōng de yí wèi.","vi":"Vào Tết Trung Thu người Trung Quốc thường sẽ về quê đón lễ. Nhưng có một số người do yêu cầu công việc không thể về nhà, chỉ đành ở lại nơi làm việc đón lễ một mình. Châu Lực chính là một trong những người như vậy."},{"speaker":"Đoạn văn","hanzi":"他是一名铁路工作人员，今年中秋假期，要负责铁路安全检查。","pinyin":"Tā shì yì míng tiělù gōngzuò rényuán, jīnnián Zhōngqiū jiàqī, yào fùzé tiělù ānquán jiǎnchá.","vi":"Anh là nhân viên ngành đường sắt, kỳ nghỉ Trung Thu năm nay phải phụ trách kiểm tra an toàn đường sắt."},{"speaker":"Đoạn văn","hanzi":"周力的父母知道儿子这次不能回家后，就决定来一次“反向团圆”。早上五点左右他们就坐上了高铁，大约七点就来到了儿子工作的城市。","pinyin":"Zhōu Lì de fùmǔ zhīdào érzi zhè cì bùnéng huíjiā hòu, jiù juédìng lái yí cì \"fǎnxiàng tuányuán\". Zǎoshang wǔ diǎn zuǒyòu tāmen jiù zuòshàng le gāotiě, dàyuē qī diǎn jiù láidào le érzi gōngzuò de chéngshì.","vi":"Bố mẹ Châu Lực biết lần này con trai không về được nên quyết định thực hiện một chuyến \"đoàn viên ngược chiều\". Khoảng 5 giờ sáng hai ông bà đã lên tàu cao tốc, tầm 7 giờ đã tới thành phố nơi con làm việc."},{"speaker":"Đoạn văn","hanzi":"在儿子家，他们做了一桌儿子爱吃的饭菜，有烤肉、烤鱼、饺子等等，还有西红柿鸡蛋汤。","pinyin":"Zài érzi jiā, tāmen zuò le yì zhuō érzi ài chī de fàncài, yǒu kǎoròu, kǎoyú, jiǎozi děngděng, hái yǒu xīhóngshì jīdàn tāng.","vi":"Tại nhà con trai, ông bà nấu cả một bàn thức ăn con thích, có thịt nướng, cá nướng, sủi cảo... và cả canh trứng cà chua."},{"speaker":"Đoạn văn","hanzi":"周力下班回家，看到一桌子饭菜和突然出现的父母，他感觉特别幸福。这个中秋节，地点变了，但爱没变。","pinyin":"Zhōu Lì xiàbān huíjiā, kàndào yì zhuōzi fàncài hé tūrán chūxiàn de fùmǔ, tā gǎnjué tèbié xìngfú. Zhège Zhōngqiūjié, dìdiǎn biàn le, dàn ài méi biàn.","vi":"Châu Lực tan làm về nhà, nhìn thấy cả bàn cơm ngon và bố mẹ bất ngờ xuất hiện, anh cảm thấy vô cùng hạnh phúc. Trung Thu năm nay địa điểm đã đổi, nhưng tình yêu thương vẫn vẹn nguyên."}],"readingQuiz":[{"q":"周力不能回家过中秋节，是因为：","options":["不想回家","工作需要","没买到车票","想去外地过节"],"answerIdx":1,"explanation":"Đoạn văn nêu \"有些人由于工作需要，不能回家... 他是一名铁路工作人员，今年中秋假期，要负责铁路安全检查。\" (Do nhu cầu công việc phải kiểm tra an toàn đường sắt)."},{"q":"中秋节这天，周力的父母为儿子做了什么？","options":["买月饼","打扫卫生","买了一件上衣","做了一桌饭菜"],"answerIdx":3,"explanation":"Trong bài viết \"在儿子家，他们做了一桌儿子爱吃的饭菜\" (Ông bà làm cả một bàn cơm món con thích ăn)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"节日的美好记忆","sceneVi":"Ký ức tươi đẹp về ngày lễ","lines":[{"speaker":"Đoạn văn","hanzi":"中国有很多节日，比如春节、元宵节、端午节、中秋节等。作为一年里最重要的传统节日，春节对中国人来说有着特别的意义。","pinyin":"Zhōngguó yǒu hěnduō jiérì, bǐrú Chūnjié, Yuánxiāojié, Duānwǔjié, Zhōngqiūjié děng. Zuòwéi yì nián lǐ zuì zhòngyào de chuántǒng jiérì, Chūnjié duì Zhōngguórén láishuō yǒuzhe tèbié de yìyì.","vi":"Trung Quốc có rất nhiều ngày lễ như Tết Nguyên Đán, Tết Nguyên Tiêu, Tết Đoan Ngọ, Tết Trung Thu... Là ngày lễ truyền thống quan trọng nhất trong năm, Tết Nguyên Đán mang ý nghĩa đặc biệt đối với người Trung Quốc."},{"speaker":"Đoạn văn","hanzi":"春节到来时，人们不管在哪里，都想回家过年。春节前也最忙，既要收拾房子、打扫卫生，又要准备各种美食。","pinyin":"Chūnjié dàolái shí, rénmen bùguǎn zài nǎlǐ, dōu xiǎng huíjiā guònián. Chūnjié qián yě zuì máng, jì yào shōushi fángzi, dǎsǎo wèishēng, yòu yào zhǔnbèi gèzhǒng měishí.","vi":"Khi Tết đến, mọi người dù ở đâu cũng muốn về nhà đón năm mới. Trước Tết cũng là lúc bận rộn nhất, vừa phải dọn dẹp nhà cửa, làm vệ sinh, vừa phải chuẩn bị đủ loại món ngon."},{"speaker":"Đoạn văn","hanzi":"除夕这天晚上，一家人一边吃年夜饭，一边看春晚。零点一到，大家互相祝新年快乐，到处都是幸福的笑声。","pinyin":"Chúxī zhè tiān wǎnshang, yìjiārén yìbiān chī niányèfàn, yìbiān kàn Chūnwǎn. Língdiǎn yí dào, dàjiā hùxiāng zhù xīnnián kuàilè, dàochù dōu shì xìngfú de xiàoshēng.","vi":"Tối Giao thừa, cả nhà vừa ăn bữa cơm tất niên vừa xem Gala Mừng Xuân. Đúng 0 giờ, mọi người chúc nhau năm mới vui vẻ, khắp nơi ngập tràn tiếng cười hạnh phúc."},{"speaker":"Đoạn văn","hanzi":"每当回忆起童年，我最美好的记忆很多也发生在过年时。虽然现在已人到中年，离开了家，但是春节仍然是我最喜欢的节日，过年时也更想父母、兄弟姐妹。","pinyin":"Měidāng huíyì qǐ tóngnián, wǒ zuì měihǎo de jìyì hěnduō yě fāshēng zài guònián shí. Suīrán xiànzài yǐ rén dào zhōngnián, líkāi le jiā, dànshì Chūnjié réngrán shì wǒ zuì xǐhuan de jiérì, guònián shí yě gèng xiǎng fùmǔ, xiōngdì jiěmèi.","vi":"Mỗi khi nhớ lại tuổi thơ, rất nhiều ký ức đẹp nhất của tôi cũng diễn ra vào dịp Tết. Tuy giờ đã bước vào tuổi trung niên và xa nhà, nhưng Tết vẫn là ngày lễ tôi thích nhất, cứ đến Tết lại càng nhớ bố mẹ và anh chị em."}],"readingQuiz":[{"q":"下列哪个节日没有提到？","options":["春节","元宵节","端午节","儿童节"],"answerIdx":3,"explanation":"Câu đầu liệt kê \"春节、元宵节、端午节、中秋节\", không nhắc tới 儿童节 (Ngày Thiếu nhi)."},{"q":"根据课文，春节到来时，人们会做什么？","options":["准备美食","外出看花","出去旅游","照顾孩子"],"answerIdx":0,"explanation":"Bài viết nêu \"既要收拾房子、打扫卫生，又要准备各种美食\" (Vừa dọn dẹp nhà cửa vừa chuẩn bị nhiều món ngon)."}]}],"hsk4b-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"周六上午，安妮到茶叶店买茶叶。","sceneVi":"Sáng thứ Bảy, An Ni đến cửa hàng trà mua lá trà.","lines":[{"speaker":"售货员","hanzi":"您要什么茶？","pinyin":"Nín yào shénme chá?","vi":"Chị muốn mua loại trà nào ạ?"},{"speaker":"安妮","hanzi":"我先看看。这里茶叶这么多，究竟买哪种好呢？","pinyin":"Wǒ xiān kànkan. Zhèlǐ cháyè zhème duō, jiūjìng mǎi nǎ zhǒng hǎo ne?","vi":"Để tôi xem qua trước đã. Trà ở đây nhiều thế này, rốt cuộc mua loại nào thì tốt nhỉ?"},{"speaker":"售货员","hanzi":"茶叶主要分为红茶、绿茶等，看您喜欢喝哪种。","pinyin":"Cháyè zhǔyào fēnwéi hóngchá, lǜchá děng, kàn nín xǐhuan hē nǎ zhǒng.","vi":"Trà chủ yếu chia thành hồng trà, lục trà..., tùy xem chị thích uống loại nào ạ."},{"speaker":"安妮","hanzi":"我想买一些自己喝，再买些送人。这种绿茶还有吗？","pinyin":"Wǒ xiǎng mǎi yìxiē zìjǐ hē, zài mǎi xiē sòngrén. Zhè zhǒng lǜchá hái yǒu ma?","vi":"Tôi muốn mua một ít để tự uống, rồi mua thêm ít làm quà biếu. Loại lục trà này vẫn còn chứ?"},{"speaker":"售货员","hanzi":"抱歉，暂时没有。如果自己喝，可以买这个绿茶，今天满二两送半两，超过半斤再送小礼物；如果送人，可以买个盒子装进去。","pinyin":"Bàoqiàn, zànshí méiyǒu. Rúguǒ zìjǐ hē, kěyǐ mǎi zhège lǜchá, jīntiān mǎn èr liǎng sòng bàn liǎng, chāoguò bàn jīn zài sòng xiǎo lǐwù; rúguǒ sòngrén, kěyǐ mǎi gè hézi zhuāng jìnqù.","vi":"Xin lỗi, tạm thời hết rồi ạ. Nếu chị tự uống có thể mua loại lục trà này, hôm nay mua đủ 2 lạng tặng nửa lạng, quá nửa cân sẽ tặng thêm quà nhỏ; nếu biếu tặng thì có thể mua một chiếc hộp đựng vào."},{"speaker":"安妮","hanzi":"嗯。那就先买六两这种绿茶吧，再买一个盒子。请帮我分着装，盒子里装半斤，剩下的用纸包一下就行。","pinyin":"Ǹg. Nà jiù xiān mǎi liù liǎng zhè zhǒng lǜchá ba, zài mǎi yígè hézi. Qǐng bāng wǒ fēnzhe zhuāng, hézi lǐ zhuāng bàn jīn, shèngxia de yòng zhǐ bāo yíxià jiù xíng.","vi":"Ừm. Vậy lấy trước 6 lạng lục trà này nhé, với mua thêm một cái hộp. Nhờ chị chia ra gói giúp tôi, trong hộp đựng nửa cân, chỗ còn lại gói giấy là được."}],"readingQuiz":[{"q":"安妮想知道：","options":["红茶的价格","绿茶的价格","有没有红茶","买哪种茶合适"],"answerIdx":3,"explanation":"An Ni hỏi \"这里茶叶这么多，究竟买哪种好呢？\" (Nhiều trà thế này, rốt cuộc mua loại nào thì tốt?)."},{"q":"安妮最后买了：","options":["半两绿茶","五两绿茶","六两绿茶","一斤绿茶"],"answerIdx":2,"explanation":"An Ni chốt \"那就先买六两这种绿茶吧，再买一个盒子。\" (Lấy trước 6 lạng lục trà này và một chiếc hộp)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"周日下午，王一雪想买运动鞋，王一飞陪她去商场。","sceneVi":"Chiều Chủ nhật, Vương Nhất Tuyết muốn mua giày thể thao, Vương Nhất Phi đi cùng chị tới trung tâm thương mại.","lines":[{"speaker":"广播员","hanzi":"各位顾客，本商场正在举办运动鞋假日低价促销活动，全场五折。","pinyin":"Gèwèi gùkè, běn shāngchǎng zhèngzài jǔbàn yùndòngxié jiàrì dījià cùxiāo huódòng, quánchǎng wǔzhé.","vi":"Kính thưa quý khách, trung tâm thương mại đang tổ chức chương trình khuyến mãi giày thể thao giá thấp ngày lễ, giảm 50% toàn bộ sản phẩm."},{"speaker":"王一雪","hanzi":"一飞，广播里说价格减了一半呢，咱们过去看看？","pinyin":"Yīfēi, guǎngbō lǐ shuō jiàgé jiǎn le yíbàn ne, zánmen guòqù kànkan?","vi":"Nhất Phi, loa thông báo giảm một nửa giá đấy, mình qua xem thử nhé?"},{"speaker":"王一飞","hanzi":"好的。不过咱们也不能只听广告说什么，还得看质量。","pinyin":"Hǎo de. Búguò zánmen yě bùnéng zhǐ tīng guǎnggào shuō shénme, hái děi kàn zhìliàng.","vi":"Được ạ. Nhưng mình cũng không thể chỉ nghe quảng cáo nói gì, còn phải xem chất lượng nữa."},{"speaker":"王一雪","hanzi":"对，首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","pinyin":"Duì, shǒuxiān kàn yàngzi xǐhuan bù xǐhuan, ránhòu zài kàn zhìliàng zěnmeyàng, jiàgé héshì bù héshì.","vi":"Đúng vậy, trước tiên xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào và giá cả có hợp lý không."},{"speaker":"售货员","hanzi":"二位看看喜欢哪双？这个牌子质量很好，今天又降价，一双减300块。","pinyin":"Èrwèi kànkan xǐhuan nǎ shuāng? Zhège páizi zhìliàng hěn hǎo, jīntiān yòu jiàngjià, yì shuāng jiǎn sānbǎi kuài.","vi":"Hai chị xem thích đôi nào ạ? Hãng này chất lượng rất tốt, hôm nay lại giảm giá, mỗi đôi giảm 300 tệ."},{"speaker":"王一雪","hanzi":"嗯，我知道这个牌子。一飞，你喜欢吗？你看，这个鞋的样式很新，价钱也不高。","pinyin":"Ǹg, wǒ zhīdào zhège páizi. Yīfēi, nǐ xǐhuan ma? Nǐ kàn, zhège xié de yàngshì hěn xīn, jiàqian yě bù gāo.","vi":"Ừ, chị biết hãng này. Nhất Phi, em có thích không? Nhìn này, kiểu giày mới lắm mà giá cũng không cao."},{"speaker":"王一飞","hanzi":"你喜欢就买吧。我再看看别的。","pinyin":"Nǐ xǐhuan jiù mǎi ba. Wǒ zài kànkan biéde.","vi":"Chị thích thì mua đi ạ. Em xem thêm đôi khác đã."},{"speaker":"王一雪","hanzi":"好的。请给我拿一双37号的吧。","pinyin":"Hǎo de. Qǐng gěi wǒ ná yì shuāng sānshíqī hào de ba.","vi":"Được. Làm ơn lấy cho tôi một đôi cỡ 37 nhé."}],"readingQuiz":[{"q":"商场做的运动鞋促销活动是：","options":["打一折","打五折","打七折","打八五折"],"answerIdx":1,"explanation":"Thông báo phát thanh nói \"全场五折\" (Giảm còn 5 phần / giảm 50% toàn bộ)."},{"q":"关于运动鞋，王一飞更重视什么？","options":["价格高不高","质量好不好","降价没降价","好不好看"],"answerIdx":1,"explanation":"Vương Nhất Phi nhắc \"咱们也不能只听广告说什么，还得看质量。\" (Còn phải xem chất lượng)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"适合，就受欢迎","sceneVi":"Phù hợp thì sẽ được yêu thích","lines":[{"speaker":"Đoạn văn","hanzi":"李文的朋友徐前在商业区开了家小店，专门卖年轻人喜欢的东西。","pinyin":"Lǐ Wén de péngyou Xú Qián zài shāngyèqū kāi le jiā xiǎodiàn, zhuānmén mài niánqīngrén xǐhuan de dōngxi.","vi":"Bạn của Lý Văn là Từ Tiền mở một cửa hàng nhỏ ở khu thương mại, chuyên bán những món đồ giới trẻ yêu thích."},{"speaker":"Đoạn văn","hanzi":"他的店里商品种类不少，既有几十年前的老游戏机，也有最近流行的盲盒等等，很吸引年轻人。","pinyin":"Tā de diàn lǐ shāngpǐn zhǒnglèi bùshǎo, jì yǒu jǐshí nián qián de lǎo yóuxìjī, yě yǒu zuìjìn liúxíng de mánghé děngděng, hěn xīyǐn niánqīngrén.","vi":"Trong tiệm chủng loại hàng hóa không ít, vừa có máy chơi game cũ từ mấy chục năm trước, vừa có hộp mù thịnh hành gần đây, rất thu hút người trẻ."},{"speaker":"Đoạn văn","hanzi":"徐前说，自己就是年轻人，知道年轻人喜欢什么。他也常和来店里的年轻顾客聊天儿，了解他们的兴趣爱好。","pinyin":"Xú Qián shuō, zìjǐ jiùshì niánqīngrén, zhīdào niánqīngrén xǐhuan shénme. Tā yě cháng hé lái diàn lǐ de niánqīng gùkè liáotiānr, liǎojiě tāmen de xìngqù àihào.","vi":"Từ Tiền bảo chính mình cũng là người trẻ nên biết giới trẻ thích gì. Anh cũng hay trò chuyện với khách hàng trẻ ghé tiệm để hiểu sở thích của họ."},{"speaker":"Đoạn văn","hanzi":"前段时间刚进的盲盒很快就卖到了缺货。许多年轻人表示，在徐前的店里能感受到快乐。","pinyin":"Qián duàn shíjiān gāng jìn de mánghé hěn kuài jiù màidào le quēhuò. Xǔduō niánqīngrén biǎoshì, zài Xú Qián de diàn lǐ néng gǎnshòu dào kuàilè.","vi":"Lô hộp mù mới nhập thời gian trước rất nhanh đã bán đến hết sạch hàng. Nhiều bạn trẻ chia sẻ rằng ở tiệm của Từ Tiền có thể cảm nhận được niềm vui."},{"speaker":"Đoạn văn","hanzi":"小店虽然小，但东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。李文觉得自己的朋友真会做生意。","pinyin":"Xiǎodiàn suīrán xiǎo, dàn dōngxi shìhé niánqīngrén, jiāshàng diànyuán tàidù yǒuhǎo, shǐde xiǎodiàn de shēngyi yuèláiyuè hǎo. Lǐ Wén juéde zìjǐ de péngyou zhēn huì zuò shēngyi.","vi":"Cửa hàng tuy nhỏ nhưng đồ đạc hợp với giới trẻ, cộng thêm thái độ nhân viên thân thiện khiến việc kinh doanh ngày càng phát đạt. Lý Văn thấy bạn mình thật khéo buôn bán."}],"readingQuiz":[{"q":"徐前店里卖的东西：","options":["不是很多","都很便宜","种类很多","只有游戏机"],"answerIdx":2,"explanation":"Đoạn văn viết \"他的店里商品种类不少，既有几十年前的老游戏机，也有最近流行的盲盒等等\" (Chủng loại hàng hóa trong tiệm không ít)."},{"q":"来徐前店里的顾客主要是：","options":["小孩子","年轻人","中年人","老年人"],"answerIdx":1,"explanation":"Tiệm chuyên bán đồ giới trẻ thích và các vị khách đến đều là \"年轻顾客 / 年轻人\"."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"合适的才是最好的","sceneVi":"Cái phù hợp mới là cái tốt nhất","lines":[{"speaker":"Đoạn văn","hanzi":"关于购物，你是一位冷静购物者，还是不冷静购物者？","pinyin":"Guānyú gòuwù, nǐ shì yí wèi lěngjìng gòuwùzhě, háishi bù lěngjìng gòuwùzhě?","vi":"Về chuyện mua sắm, bạn là người tiêu dùng lý trí hay người mua sắm bốc đồng?"},{"speaker":"Đoạn văn","hanzi":"一般来说，冷静购物者往往是真正需要一件东西时才买。购买时，还会从质量、价格等各方面仔细比较。","pinyin":"Yìbān láishuō, lěngjìng gòuwùzhě wǎngwǎng shì zhēnzhèng xūyào yí jiàn dōngxi shí cái mǎi. Gòumǎi shí, hái huì cóng zhìliàng, jiàgé děng gè fāngmiàn zǐxì bǐjiào.","vi":"Thông thường, người mua sắm lý trí thường chỉ mua khi thực sự cần một món đồ nào đó. Khi mua còn so sánh kỹ càng từ chất lượng, giá cả đến nhiều mặt khác."},{"speaker":"Đoạn văn","hanzi":"不冷静购物者看见一个东西时，只要感觉喜欢就买，不管需要不需要，结果常常买完就后悔，买的东西也成了“垃圾”，还不环保。","pinyin":"Bù lěngjìng gòuwùzhě kànjiàn yígè dōngxi shí, zhǐyào gǎnjué xǐhuan jiù mǎi, bùguǎn xūyào bù xūyào, jiéguǒ chángcháng mǎiwán jiù hòuhuǐ, mǎi de dōngxi yě chéng le \"lājī\", hái bù huánbǎo.","vi":"Người mua sắm thiếu bình tĩnh hễ thấy món gì chỉ cần thích là mua, mặc kệ có cần hay không, kết quả thường mua xong là hối hận, đồ mua về hóa thành \"rác\" lại còn không thân thiện môi trường."},{"speaker":"Đoạn văn","hanzi":"王一飞说，她从来不随便买东西。对于想买的东西，她不光看质量，还看价格。无论是一件外套，还是一条裤子，甚至一双袜子，都是仔细比较后才决定买不买。","pinyin":"Wáng Yīfēi shuō, tā cónglái bù suíbiàn mǎi dōngxi. Duìyú xiǎng mǎi de dōngxi, tā bùguāng kàn zhìliàng, hái kàn jiàgé. Wúlùn shì yí jiàn wàitào, háishi yì tiáo kùzi, shènzhì yì shuāng wàzi, dōu shì zǐxì bǐjiào hòu cái juédìng mǎi bù mǎi.","vi":"Vương Nhất Phi bảo cô chưa bao giờ mua sắm tùy tiện. Với món muốn mua, cô không chỉ xem chất lượng mà còn xem giá cả. Dù là một chiếc áo khoác, một chiếc quần hay thậm chí một đôi tất đều so sánh cẩn thận rồi mới quyết định mua hay không."},{"speaker":"Đoạn văn","hanzi":"其实，不仅是买东西，人生的很多事情都一样，选择合适的才是最好的。","pinyin":"Qíshí, bùjǐn shì mǎi dōngxi, rénshēng de hěnduō shìqing dōu yíyàng, xuǎnzé héshì de cái shì zuì hǎo de.","vi":"Thực ra không chỉ mua đồ, rất nhiều chuyện trong cuộc đời cũng vậy, chọn được điều phù hợp mới là tốt nhất."}],"readingQuiz":[{"q":"冷静购物者买东西时会怎么做？","options":["想买就买","喜欢就买","需要才买","很少买东西"],"answerIdx":2,"explanation":"Bài viết nêu \"冷静购物者往往是真正需要一件东西时才买。\" (Người mua sắm bình tĩnh thường thật sự cần mới mua)."},{"q":"买东西时王一飞会怎么做？","options":["只看广告","问售货员","比较一下就买","仔细比较后才买"],"answerIdx":3,"explanation":"Trong bài viết \"都是仔细比较后才决定买不买。\" (Đều so sánh cẩn thận rồi mới quyết định mua hay không)."}]}],"hsk4b-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"李文来到陈天中的学校，跟他边走边聊。","sceneVi":"Lý Văn đến trường của Trần Thiên Trung, vừa đi bộ vừa trò chuyện với cậu ấy.","lines":[{"speaker":"陈天中","hanzi":"李文，期中考试后就再也没见过你了，你这段时间在忙什么呢？","pinyin":"Lǐ Wén, qīzhōng kǎoshì hòu jiù zài yě méi jiàn guo nǐ le, nǐ zhè duàn shíjiān zài máng shénme ne?","vi":"Lý Văn, sau kỳ thi giữa kỳ đến giờ chẳng gặp cậu nữa, dạo này cậu đang bận gì thế?"},{"speaker":"李文","hanzi":"我最近去一家医药公司应聘了，他们正在招聘实习生。","pinyin":"Wǒ zuìjìn qù yì jiā yīyào gōngsī yìngpìn le, tāmen zhèngzài zhāopìn shíxíshēng.","vi":"Gần đây mình đi ứng tuyển ở một công ty dược phẩm, họ đang tuyển thực tập sinh."},{"speaker":"陈天中","hanzi":"你这么早就考虑实习了？","pinyin":"Nǐ zhème zǎo jiù kǎolǜ shíxí le?","vi":"Cậu đã tính đến chuyện thực tập sớm thế à?"},{"speaker":"李文","hanzi":"现在很多单位在招聘毕业生时，都很重视有没有实习经历，所以我想提前去锻炼一下，积累一些经验。","pinyin":"Xiànzài hěnduō dānwèi zài zhāopìn bìyèshēng shí, dōu hěn zhòngshì yǒu méiyǒu shíxí jīnglì, suǒyǐ wǒ xiǎng tíqián qù duànliàn yíxià, jīlěi yìxiē jīngyàn.","vi":"Hiện nay nhiều đơn vị khi tuyển sinh viên tốt nghiệp đều rất coi trọng việc có kinh nghiệm thực tập hay không, nên mình muốn đi rèn luyện trước để tích lũy ít kinh nghiệm."},{"speaker":"陈天中","hanzi":"那现在有结果了吗？","pinyin":"Nà xiànzài yǒu jiéguǒ le ma?","vi":"Thế giờ có kết quả chưa?"},{"speaker":"李文","hanzi":"我还在等消息，希望能有好结果。","pinyin":"Wǒ hái zài děng xiāoxi, xīwàng néng yǒu hǎo jiéguǒ.","vi":"Mình vẫn đang đợi tin, hy vọng sẽ có kết quả tốt."}],"readingQuiz":[{"q":"李文最近在忙什么？","options":["去公司应聘","在公司实习","准备期中考试","为毕业做准备"],"answerIdx":0,"explanation":"Lý Văn nói \"我最近去一家医药公司应聘了，他们正在招聘实习生。\" (Gần đây mình đi ứng tuyển ở công ty dược phẩm)."},{"q":"很多单位招聘毕业生时，比较重视什么？","options":["身体情况","学习成绩","实习经历","毕业的学校"],"answerIdx":2,"explanation":"Trong bài Lý Văn nói rõ \"很多单位在招聘毕业生时，都很重视有没有实习经历\" (Rất coi trọng có kinh nghiệm thực tập hay không)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"在校园，陈天中和李文边走边聊。","sceneVi":"Trong khuôn viên trường, Trần Thiên Trung và Lý Văn vừa đi vừa trò chuyện.","lines":[{"speaker":"陈天中","hanzi":"李文，你是怎么应聘的？","pinyin":"Lǐ Wén, nǐ shì zěnme yìngpìn de?","vi":"Lý Văn, cậu ứng tuyển bằng cách nào thế?"},{"speaker":"李文","hanzi":"我先在网上报名，填写个人信息，然后等公司通知我去参加笔试。","pinyin":"Wǒ xiān zài wǎngshàng bàomíng, tiánxiě gèrén xìnxī, ránhòu děng gōngsī tōngzhī wǒ qù cānjiā bǐshì.","vi":"Trước tiên mình đăng ký trên mạng, điền thông tin cá nhân, rồi đợi công ty thông báo đi thi viết."},{"speaker":"陈天中","hanzi":"笔试都考些什么？","pinyin":"Bǐshì dōu kǎo xiē shénme?","vi":"Bài thi viết thi những gì vậy?"},{"speaker":"李文","hanzi":"主要是一些专业知识。考完没多久，他们就让我去面试了。","pinyin":"Zhǔyào shì yìxiē zhuānyè zhīshi. Kǎowán méi duōjiǔ, tāmen jiù ràng wǒ qù miànshì le.","vi":"Chủ yếu là một số kiến thức chuyên ngành. Thi xong chưa lâu họ đã gọi mình đi phỏng vấn rồi."},{"speaker":"陈天中","hanzi":"看来你笔试答得不错，那你面试得怎么样？","pinyin":"Kànlái nǐ bǐshì dá de búcuò, nà nǐ miànshì de zěnmeyàng?","vi":"Xem ra cậu làm bài thi viết khá ổn, thế buổi phỏng vấn thế nào?"},{"speaker":"李文","hanzi":"那天是由部门负责人来面试的，我有点儿紧张。他让我介绍了自己的学习经历、兴趣爱好和对工作的想法。","pinyin":"Nàtiān shì yóu bùmén fùzérén lái miànshì de, wǒ yǒudiǎnr jǐnzhāng. Tā ràng wǒ jièshào le zìjǐ de xuéxí jīnglì, xìngqù àihào hé duì gōngzuò de xiǎngfǎ.","vi":"Hôm đó người phụ trách phòng ban trực tiếp phỏng vấn nên mình hơi hồi hộp. Anh ấy bảo mình giới thiệu quá trình học tập, sở thích và suy nghĩ về công việc."},{"speaker":"陈天中","hanzi":"听起来挺正式的。","pinyin":"Tīng qǐlái tǐng zhèngshì de.","vi":"Nghe có vẻ rất trang trọng đấy."},{"speaker":"李文","hanzi":"是啊，我觉得这次经历很有用。不论结果怎么样，对我以后找工作肯定有帮助。","pinyin":"Shì a, wǒ juéde zhè cì jīnglì hěn yǒuyòng. Búlùn jiéguǒ zěnmeyàng, duì wǒ yǐhòu zhǎo gōngzuò kěndìng yǒu bāngzhù.","vi":"Đúng vậy, mình thấy trải nghiệm lần này rất hữu ích. Bất kể kết quả thế nào, chắc chắn cũng có ích cho việc tìm việc sau này của mình."}],"readingQuiz":[{"q":"李文应聘时，第一步做的是什么？","options":["参加笔试","参加面试","在网上报名","给负责人打电话"],"answerIdx":2,"explanation":"Lý Văn nói \"我先在网上报名，填写个人信息，然后等公司通知我去参加笔试。\" (Trước tiên đăng ký trên mạng)."},{"q":"公司的笔试主要考什么？","options":["外语水平","专业知识","兴趣爱好","对工作的想法"],"answerIdx":1,"explanation":"Lý Văn trả lời \"主要是一些专业知识。\" (Chủ yếu là một số kiến thức chuyên ngành)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"在家里，李文收到了公司发来的短信。","sceneVi":"Ở nhà, Lý Văn nhận được tin nhắn từ công ty gửi tới.","lines":[{"speaker":"Đoạn văn","hanzi":"一天下午，李文突然收到一条短信，说他通过了面试，让他下周一到公司实习。李文看到信息后，激动得把手机扔到床上，在屋子里跳了起来。","pinyin":"Yìtiān xiàwǔ, Lǐ Wén tūrán shōudào yì tiáo duǎnxìn, shuō tā tōngguò le miànshì, ràng tā xià Zhōuyī dào gōngsī shíxí. Lǐ Wén kàndào xìnxī hòu, jīdòng de bǎ shǒujī rēngdào chuángshàng, zài wūzi lǐ tiào le qǐlái.","vi":"Một buổi chiều, Lý Văn bỗng nhận được tin nhắn báo anh đã đậu phỏng vấn và mời thứ Hai tuần sau đến công ty thực tập. Đọc tin xong, Lý Văn xúc động đến mức ném điện thoại lên giường rồi nhảy cẫng lên trong phòng."},{"speaker":"Đoạn văn","hanzi":"之后的几天，李文忙着做各种准备。为了给大家留个好印象，他去理发店把头发理了理，又去商店买了一身正式的衣服，还打算在镜子前把自我介绍练一练。","pinyin":"Zhīhòu de jǐ tiān, Lǐ Wén mángzhe zuò gèzhǒng zhǔnbèi. Wèile gěi dàjiā liú gè hǎo yìnxiàng, tā qù lǐfàdiàn bǎ tóufa lǐ le lǐ, yòu qù shāngdiàn mǎi le yì shēn zhèngshì de yīfu, hái dǎsuàn zài jìngzi qián bǎ zìwǒ jièshào liàn yí liàn.","vi":"Mấy ngày sau đó, Lý Văn tất bật chuẩn bị đủ thứ. Để tạo ấn tượng tốt với mọi người, anh ra tiệm cắt tóc chỉnh lại đầu tóc, rồi đi cửa hàng mua một bộ quần áo trang trọng, còn định đứng trước gương luyện lại phần tự giới thiệu."},{"speaker":"Đoạn văn","hanzi":"在他看来，这次实习是一个新的开始。他希望不仅能够运用专业知识完成任务，还能够积累更多经验，为将来找工作打下基础。","pinyin":"Zài tā kànlái, zhè cì shíxí shì yígè xīn de kāishǐ. Tā xīwàng bùjǐn nénggòu yùnyòng zhuānyè zhīshi wánchéng rènwu, hái nénggòu jīlěi gèng duō jīngyàn, wèi jiānglái zhǎo gōngzuò dǎxià jīchǔ.","vi":"Trong mắt anh, đợt thực tập lần này là một khởi đầu mới. Anh hy vọng không chỉ vận dụng được kiến thức chuyên môn để hoàn thành nhiệm vụ mà còn tích lũy thêm nhiều kinh nghiệm, đặt nền móng cho việc tìm việc sau này."}],"readingQuiz":[{"q":"李文收到的短信内容是什么？","options":["他通过面试了","他周末得加班","他明天要开始工作","他下周工作任务多"],"answerIdx":0,"explanation":"Đoạn văn viết \"收到一条短信，说他通过了面试，让他下周一到公司实习。\" (Tin nhắn báo cậu ấy đã qua vòng phỏng vấn)."},{"q":"李文做了什么准备？","options":["搬到了公司附近","买了一个新手机","买了一身新衣服","去商场买礼物了"],"answerIdx":2,"explanation":"Trong bài viết \"他去理发店把头发理了理，又去商店买了一身正式的衣服\" (Đi cắt tóc và mua một bộ quần áo trang trọng mới)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"实习的收获","sceneVi":"Những thu hoạch từ kỳ thực tập","lines":[{"speaker":"Đoạn văn","hanzi":"在中国，很多大学生在毕业前都会去实习。实习的地方有公司、工厂，也有学校和医院。","pinyin":"Zài Zhōngguó, hěnduō dàxuéshēng zài bìyè qián dōu huì qù shíxí. Shíxí de dìfang yǒu gōngsī, gōngchǎng, yě yǒu xuéxiào hé yīyuàn.","vi":"Ở Trung Quốc, rất nhiều sinh viên đại học trước khi tốt nghiệp đều đi thực tập. Nơi thực tập có công ty, nhà máy, cũng có trường học và bệnh viện."},{"speaker":"Đoạn văn","hanzi":"学生们通过实习，可以积累工作经验，熟悉工作内容和单位的管理规定，提前了解并适应社会。","pinyin":"Xuéshengmen tōngguò shíxí, kěyǐ jīlěi gōngzuò jīngyàn, shúxi gōngzuò nèiróng hé dānwèi de guǎnlǐ guīdìng, tíqián liǎojiě bìng shìyìng shèhuì.","vi":"Thông qua thực tập, sinh viên có thể tích lũy kinh nghiệm làm việc, làm quen nội dung công việc và quy định quản lý của đơn vị, tìm hiểu và thích nghi trước với xã hội."},{"speaker":"Đoạn văn","hanzi":"在实习中，学生常常会发现，课堂上学到的知识和实际工作并不完全一样。例如：有些事情，在课本上学不如自己做一遍，因为只有在做的时候，才会发现有很多细节需要注意；还有一些问题，在书上找不到答案，只能通过日常工作慢慢理解。","pinyin":"Zài shíxí zhōng, xuésheng chángcháng huì fāxiàn, kètáng shàng xuédào de zhīshi hé shíjì gōngzuò bìng bù wánquán yíyàng. Lìrú: yǒuxiē shìqing, zài kèběn shàng xué bùrú zìjǐ zuò yíbiàn, yīnwèi zhǐyǒu zài zuò de shíhou, cái huì fāxiàn yǒu hěnduō xìjié xūyào zhùyì; hái yǒu yìxiē wèntí, zài shūshàng zhǎo bú dào dá'àn, zhǐnéng tōngguò rìcháng gōngzuò mànmàn lǐjiě.","vi":"Trong lúc thực tập, sinh viên thường phát hiện kiến thức học trên lớp không hoàn toàn giống công việc thực tế. Ví dụ có những việc học trong sách không bằng tự làm một lần, vì chỉ khi làm mới thấy nhiều chi tiết cần chú ý; còn có những vấn đề không tìm thấy đáp án trong sách, chỉ có thể hiểu dần qua công việc hằng ngày."},{"speaker":"Đoạn văn","hanzi":"在这样的过程中，学生能够对学到的知识有更好的认识，也更清楚自己的职业发展方向。","pinyin":"Zài zhèyàng de guòchéng zhōng, xuésheng nénggòu duì xuédào de zhīshi yǒu gèng hǎo de rènshi, yě gèng qīngchu zìjǐ de zhíyè fāzhǎn fāngxiàng.","vi":"Trong quá trình đó, sinh viên có nhận thức tốt hơn về kiến thức đã học và cũng xác định rõ hơn định hướng phát triển nghề nghiệp của mình."}],"readingQuiz":[{"q":"根据课文，为什么很多大学生要去实习？","options":["想认识新朋友","便于了解社会","想减轻经济压力","为了达到毕业要求"],"answerIdx":1,"explanation":"Đoạn văn nêu \"可以积累工作经验... 提前了解并适应社会\" (Giúp tìm hiểu và thích nghi trước với xã hội)."},{"q":"在实习中，学生们会有什么发现？","options":["工作比学习更简单","书上的知识没有用","学习时要注意细节","有的问题要慢慢理解"],"answerIdx":3,"explanation":"Bài viết nêu rõ \"还有一些问题，在书上找不到答案，只能通过日常工作慢慢理解。\" (Có những vấn đề chỉ có thể hiểu dần qua công việc hằng ngày)."}]}],"hsk4b-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"在王一雪家，王一雪和白家月在聊天儿。","sceneVi":"Tại nhà Vương Nhất Tuyết, Vương Nhất Tuyết và Bạch Gia Nguyệt đang trò chuyện.","lines":[{"speaker":"王一雪","hanzi":"家月，周末你还打算去南京旅游吗？我去年去过那里，可以给你介绍一下。","pinyin":"Jiāyuè, zhōumò nǐ hái dǎsuàn qù Nánjīng lǚyóu ma? Wǒ qùnián qù guo nàlǐ, kěyǐ gěi nǐ jièshào yíxià.","vi":"Gia Nguyệt, cuối tuần em vẫn định đi du lịch Nam Kinh chứ? Năm ngoái chị từng đến đó, có thể giới thiệu cho em một chút."},{"speaker":"白家月","hanzi":"本来都计划好了，可是昨天突然接到通知，下周学校要安排一次考试，所以周末只好在家复习了。","pinyin":"Běnlái dōu jìhuà hǎo le, kěshì zuótiān tūrán jiēdào tōngzhī, xiàzhōu xuéxiào yào ānpái yí cì kǎoshì, suǒyǐ zhōumò zhǐhǎo zài jiā fùxí le.","vi":"Vốn dĩ em đã lên kế hoạch xong cả rồi, nhưng hôm qua đột nhiên nhận thông báo tuần sau trường sắp xếp một kỳ thi, nên cuối tuần đành ở nhà ôn tập thôi ạ."},{"speaker":"王一雪","hanzi":"真是计划赶不上变化啊！看来你的旅行计划只能推迟了。","pinyin":"Zhēnshi jìhuà gǎn bú shàng biànhuà a! Kànlái nǐ de lǚxíng jìhuà zhǐnéng tuīchí le.","vi":"Đúng là kế hoạch không theo kịp thay đổi! Xem ra kế hoạch du lịch của em chỉ đành hoãn lại rồi."},{"speaker":"白家月","hanzi":"是的，我已经把机票和酒店取消了。虽然有点儿可惜，但学习更重要。","pinyin":"Shì de, wǒ yǐjīng bǎ jīpiào hé jiǔdiàn qǔxiāo le. Suīrán yǒudiǎnr kěxī, dàn xuéxí gèng zhòngyào.","vi":"Vâng ạ, em đã hủy vé máy bay và khách sạn rồi. Tuy hơi tiếc chút nhưng việc học quan trọng hơn."},{"speaker":"王一雪","hanzi":"学习确实要放在第一位。等到考试结束后，你再找个时间去。","pinyin":"Xuéxí quèshí yào fàng zài dì yī wèi. Děngdào kǎoshì jiéshù hòu, nǐ zài zhǎo gè shíjiān qù.","vi":"Học tập quả thực phải đặt lên hàng đầu. Đợi sau khi thi xong em lại tìm dịp đi sau."},{"speaker":"白家月","hanzi":"我也是这么想的，以后肯定还有很多机会。","pinyin":"Wǒ yě shì zhème xiǎng de, yǐhòu kěndìng hái yǒu hěnduō jīhuì.","vi":"Em cũng nghĩ vậy ạ, sau này chắc chắn vẫn còn nhiều cơ hội."}],"readingQuiz":[{"q":"白家月本来计划周末做什么？","options":["去旅游","买机票","订酒店","在家复习"],"answerIdx":0,"explanation":"Vương Nhất Tuyết hỏi \"周末你还打算去南京旅游吗？\" và Gia Nguyệt đáp \"本来都计划好了\"."},{"q":"王一雪建议白家月什么时候去旅游？","options":["明天","这个周末","下个周末","考试结束后"],"answerIdx":3,"explanation":"Vương Nhất Tuyết khuyên \"等到考试结束后，你再找个时间去。\" (Đợi sau khi thi kết thúc hãy tìm thời gian đi)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"在公司，王一雪和杨同乐在谈论工作。","sceneVi":"Tại công ty, Vương Nhất Tuyết và Dương Đồng Nhạc đang trao đổi công việc.","lines":[{"speaker":"杨同乐","hanzi":"刚接到通知，明天早晨的会议，时间改到下周了。","pinyin":"Gāng jiēdào tōngzhī, míngtiān zǎochen de huìyì, shíjiān gǎidào xiàzhōu le.","vi":"Vừa nhận được thông báo cuộc họp sáng mai đổi lịch sang tuần sau rồi."},{"speaker":"王一雪","hanzi":"啊？时间都安排好了，怎么说变就变了？","pinyin":"Á? Shíjiān dōu ānpái hǎo le, zěnme shuō biàn jiù biàn le?","vi":"Hả? Thời gian sắp xếp ổn thỏa hết rồi, sao nói đổi là đổi ngay thế?"},{"speaker":"杨同乐","hanzi":"是啊，没想到忽然要改时间。","pinyin":"Shì a, méi xiǎngdào hūrán yào gǎi shíjiān.","vi":"Đúng đấy, không ngờ tự dưng lại phải đổi giờ."},{"speaker":"王一雪","hanzi":"好吧，那再看看有没有新的安排，或者增加的会议内容。","pinyin":"Hǎo ba, nà zài kànkan yǒu méiyǒu xīn de ānpái, huòzhě zēngjiā de huìyì nèiróng.","vi":"Được rồi, vậy xem lại xem có sắp xếp mới hay nội dung cuộc họp nào được bổ sung không."},{"speaker":"杨同乐","hanzi":"好的。会议材料还需要调整吗？","pinyin":"Hǎo de. Huìyì cáiliào hái xūyào tiáozhěng ma?","vi":"Vâng. Tài liệu cuộc họp còn cần điều chỉnh gì nữa không ạ?"},{"speaker":"王一雪","hanzi":"再检查一下有没有细节上的错误，并且试着增加一些例子，把内容准备得更全一些。","pinyin":"Zài jiǎnchá yíxià yǒu méiyǒu xìjié shàng de cuòwù, bìngqiě shìzhe zēngjiā yìxiē lìzi, bǎ nèiróng zhǔnbèi de gèng quán yìxiē.","vi":"Kiểm tra lại một lượt xem có lỗi sai về chi tiết không, đồng thời thử thêm một số ví dụ, chuẩn bị nội dung đầy đủ hơn chút nữa."},{"speaker":"杨同乐","hanzi":"没问题，这样效果肯定会更好。","pinyin":"Méi wèntí, zhèyàng xiàoguǒ kěndìng huì gèng hǎo.","vi":"Không thành vấn đề, làm vậy hiệu quả chắc chắn sẽ tốt hơn."},{"speaker":"王一雪","hanzi":"看来有时候变化不一定是坏事，关键是我们怎么去适应变化。","pinyin":"Kànlái yǒu shíhou biànhuà bù yídìng shì huàishì, guānjiàn shì wǒmen zěnme qù shìyìng biànhuà.","vi":"Xem ra đôi khi sự thay đổi chưa hẳn là chuyện xấu, mấu chốt là chúng ta thích nghi với thay đổi như thế nào."}],"readingQuiz":[{"q":"杨同乐接到了什么通知？","options":["会议时间变化了","会议材料要调整","会议地点变化了","会议内容增加了"],"answerIdx":0,"explanation":"Dương Đồng Nhạc mở đầu nói \"明天早晨的会议，时间改到下周了。\" (Thời gian cuộc họp đổi sang tuần sau)."},{"q":"王一雪让杨同乐做什么？","options":["检查细节问题","重新准备材料","通知会议地点","安排会议时间"],"answerIdx":0,"explanation":"Vương Nhất Tuyết dặn \"再检查一下有没有细节上的错误，并且试着增加一些例子\" (Kiểm tra lại xem có lỗi chi tiết không)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"在课堂上，白家月表达自己对做计划的看法。","sceneVi":"Trên lớp học, Bạch Gia Nguyệt chia sẻ quan điểm của bản thân về việc lập kế hoạch.","lines":[{"speaker":"Đoạn văn","hanzi":"在生活和工作中，有的人喜欢做计划，他们会提前安排好每天要做的事情，然后按照详细的时间表去完成任务，觉得这样做更有把握。","pinyin":"Zài shēnghuó hé gōngzuò zhōng, yǒude rén xǐhuan zuò jìhuà, tāmen huì tíqián ānpái hǎo měitiān yào zuò de shìqing, ránhòu ànzhào xiángxì de shíjiānbiǎo qù wánchéng rènwu, juéde zhèyàng zuò gèng yǒu bǎwò.","vi":"Trong cuộc sống và công việc, có người thích lập kế hoạch; họ sắp xếp trước việc cần làm mỗi ngày rồi hoàn thành nhiệm vụ theo thời gian biểu chi tiết, cảm thấy làm thế chắc chắn hơn."},{"speaker":"Đoạn văn","hanzi":"相反，也有一部分人不爱做计划，他们认为随意一些也很好，想到什么就去做什么，感觉这样比较轻松。","pinyin":"Xiāngfǎn, yě yǒu yí bùfen rén bú ài zuò jìhuà, tāmen rènwéi suíyì yìxiē yě hěn hǎo, xiǎngdào shénme jiù qù zuò shénme, gǎnjué zhèyàng bǐjiào qīngsōng.","vi":"Ngược lại, cũng có một bộ phận người không thích lập kế hoạch, họ cho rằng tùy hứng một chút cũng rất ổn, nghĩ ra việc gì thì làm việc đó, cảm thấy vậy thoải mái hơn."},{"speaker":"Đoạn văn","hanzi":"其实，事前做计划是好是坏没有标准答案。严格按照计划做事，常常能取得不错的效果；而不做计划，说不定也会带来新的发现。","pinyin":"Qíshí, shìqián zuò jìhuà shì hǎo shì huài méiyǒu biāozhǔn dá'àn. Yángé ànzhào jìhuà zuòshì, chángcháng néng qǔdé búcuò de xiàoguǒ; ér bú zuò jìhuà, shuōbudìng yě huì dàilái xīn de fāxiàn.","vi":"Thực ra việc lập kế hoạch trước là tốt hay xấu không có đáp án chuẩn duy nhất. Làm việc nghiêm túc theo kế hoạch thường đạt hiệu quả khá tốt; còn không lập kế hoạch biết đâu cũng mang lại những phát hiện mới mẻ."},{"speaker":"Đoạn văn","hanzi":"无论做不做计划，只要既能按时完成任务，又能根据情况灵活调整，就是适合自己的方式。","pinyin":"Wúlùn zuò bú zuò jìhuà, zhǐyào jì néng ànshí wánchéng rènwu, yòu néng gēnjù qíngkuàng línghuó tiáozhěng, jiùshì shìhé zìjǐ de fāngshì.","vi":"Bất kể có lập kế hoạch hay không, chỉ cần vừa hoàn thành nhiệm vụ đúng hạn vừa linh hoạt điều chỉnh theo tình hình thì đó là phương pháp phù hợp với bản thân."}],"readingQuiz":[{"q":"有的人为什么喜欢做计划？","options":["可以省钱","可以省时间","做事更有把握","感觉比较轻松"],"answerIdx":2,"explanation":"Câu đầu nêu \"觉得这样做更有把握\" (Cảm thấy làm như vậy có phần nắm chắc hơn)."},{"q":"根据课文，不做计划可能会有什么结果？","options":["带来新的发现","让任务变简单","提前完成任务","增加工作压力"],"answerIdx":0,"explanation":"Đoạn văn nói \"而不做计划，说不定也会带来新的发现。\" (Biết đâu cũng mang lại những phát hiện mới)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"计划与变化","sceneVi":"Kế hoạch và sự thay đổi","lines":[{"speaker":"Đoạn văn","hanzi":"人们常说“计划赶不上变化”。有时候，你准备好了一切，却突然出现了新情况，让你不得不改变计划。","pinyin":"Rénmen cháng shuō \"Jìhuà gǎn bú shàng biànhuà\". Yǒu shíhou, nǐ zhǔnbèi hǎo le yíqiè, què tūrán chūxiàn le xīn qíngkuàng, ràng nǐ bùdébù gǎibiàn jìhuà.","vi":"Người ta thường nói \"Kế hoạch không theo kịp thay đổi\". Có lúc bạn đã chuẩn bị xong xuôi mọi thứ, nhưng đột nhiên xuất hiện tình huống mới khiến bạn buộc phải thay đổi kế hoạch."},{"speaker":"Đoạn văn","hanzi":"比如准备出去旅行，可能因为有事而取消；约好见朋友，可能因为天气不好而推迟。","pinyin":"Bǐrú zhǔnbèi chūqù lǚxíng, kěnéng yīnwèi yǒushì ér qǔxiāo; yuēhǎo jiàn péngyou, kěnéng yīnwèi tiānqì bù hǎo ér tuīchí.","vi":"Ví dụ chuẩn bị đi du lịch có thể vì có việc mà hủy bỏ; hẹn gặp bạn bè có thể vì thời tiết xấu mà hoãn lại."},{"speaker":"Đoạn văn","hanzi":"虽然变化经常打乱计划，给我们带来不便，甚至让人感到失望，但这些变化也许会给生活带来新的可能。","pinyin":"Suīrán biànhuà jīngcháng dǎluàn jìhuà, gěi wǒmen dàilái búbiàn, shènzhì ràng rén gǎndào shīwàng, dàn zhèxiē biànhuà yěxǔ huì gěi shēnghuó dàilái xīn de kěnéng.","vi":"Tuy thay đổi hay làm xáo trộn kế hoạch, mang lại bất tiện và thậm chí khiến ta thất vọng, nhưng những biến đổi ấy biết đâu sẽ đem đến cho cuộc sống những khả năng mới."},{"speaker":"Đoạn văn","hanzi":"比如没去成旅行，于是在家门口的小公园逛了逛，发现那里也很有趣；没见到朋友，于是在家观看了一部电影，心情也变得很愉快。","pinyin":"Bǐrú méi qù chéng lǚxíng, yúshì zài jiāménkǒu de xiǎo gōngyuán guàng le guàng, fāxiàn nàlǐ yě hěn yǒuqù; méi jiàndào péngyou, yúshì zài jiā guānkàn le yí bù diànyǐng, xīnqíng yě biànde hěn yúkuài.","vi":"Chẳng hạn không đi du lịch được bèn dạo chơi công viên nhỏ gần nhà và nhận ra nơi đó cũng rất thú vị; không gặp được bạn bèn ở nhà xem một bộ phim, tâm trạng cũng trở nên rất vui vẻ."},{"speaker":"Đoạn văn","hanzi":"生活中很多变化是无法提前知道的，我们要做的就是学会接受变化、适应变化，在变化中找到新的解决办法。这样不仅能锻炼自己在面对不同情况时解决问题的能力，也能让我们的生活更轻松。","pinyin":"Shēnghuó zhōng hěnduō biànhuà shì wúfǎ tíqián zhīdào de, wǒmen yào zuò de jiùshì xuéhuì jiēshòu biànhuà, shìyìng biànhuà, zài biànhuà zhōng zhǎodào xīn de jiějué bànfǎ. Zhèyàng bùjǐn néng duànliàn zìjǐ zài miànduì bùtóng qíngkuàng shí jiějué wèntí de nénglì, yě néng ràng wǒmen de shēnghuó gèng qīngsōng.","vi":"Rất nhiều thay đổi trong cuộc sống không thể biết trước được, điều ta cần làm là học cách chấp nhận, thích nghi với thay đổi và tìm hướng giải quyết mới ngay trong biến động ấy. Làm vậy không chỉ rèn năng lực xử lý tình huống khác nhau mà còn khiến cuộc sống nhẹ nhàng hơn."}],"readingQuiz":[{"q":"根据课文，变化可能会带来什么影响？","options":["心情变得更加愉快","以后不用再做计划","让事情更容易完成","给生活带来新可能"],"answerIdx":3,"explanation":"Đoạn văn viết \"但这些变化也许会给生活带来新的可能。\" (Những thay đổi ấy có lẽ sẽ mang lại cho cuộc sống những khả năng mới)."},{"q":"面对变化，人们应该怎么做？","options":["随意地安排计划","坚持本来的计划","发现并解决问题","接受并适应变化"],"answerIdx":3,"explanation":"Câu kết nêu \"我们要做的就是学会接受变化、适应变化，在变化中找到新的解决办法。\" (Học cách chấp nhận và thích nghi với sự thay đổi)."}]}],"hsk4b-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"在公司，王一雪准备下班，跟杨同乐打了个招呼。","sceneVi":"Ở công ty, Vương Nhất Tuyết chuẩn bị tan làm, chào hỏi Dương Đồng Nhạc một tiếng.","lines":[{"speaker":"王一雪","hanzi":"下班了！同乐，我今天正好要路过你们家那边，用不用我开车送你？","pinyin":"Xiàbān le! Tónglè, wǒ jīntiān zhènghǎo yào lùguò nǐmen jiā nàbiān, yòng bú yòng wǒ kāichē sòng nǐ?","vi":"Tan làm rồi! Đồng Nhạc, hôm nay chị vừa hay đi ngang khu nhà em, có cần chị lái xe đưa về không?"},{"speaker":"杨同乐","hanzi":"谢谢一雪姐，不过您走您的吧，我一会儿还要去一趟健身房。","pinyin":"Xièxie Yīxuě jiě, búguò nín zǒu nín de ba, wǒ yíhuìr hái yào qù yí tàng jiànshēnfáng.","vi":"Cảm ơn chị Nhất Tuyết, nhưng chị cứ đi đường chị nhé, lát nữa em còn qua phòng gym một chuyến."},{"speaker":"王一雪","hanzi":"去健身房？你什么时候开始健身的？","pinyin":"Qù jiànshēnfáng? Nǐ shénme shíhou kāishǐ jiànshēn de?","vi":"Đi phòng gym à? Em bắt đầu tập gym từ lúc nào thế?"},{"speaker":"杨同乐","hanzi":"我上个星期发现单位旁边新开了一家健身房。我最近体重增加了不少，正好想运动一下，就进去看了看。","pinyin":"Wǒ shàng gè xīngqī fāxiàn dānwèi pángbiān xīn kāi le yì jiā jiànshēnfáng. Wǒ zuìjìn tǐzhòng zēngjiā le bùshǎo, zhènghǎo xiǎng yùndòng yíxià, jiù jìnqù kàn le kàn.","vi":"Tuần trước em phát hiện cạnh cơ quan mới mở một phòng tập gym. Dạo này cân nặng của em tăng lên khá nhiều, đúng lúc đang muốn vận động nên vào xem thử."},{"speaker":"王一雪","hanzi":"感觉怎么样？","pinyin":"Gǎnjué zěnmeyàng?","vi":"Cảm thấy thế nào?"},{"speaker":"杨同乐","hanzi":"挺不错的。当时正好有打折活动，我就办了一张会员卡。","pinyin":"Tǐng búcuò de. Dāngshí zhènghǎo yǒu dǎzhé huódòng, wǒ jiù bàn le yì zhāng huìyuánkǎ.","vi":"Khá ổn chị ạ. Lúc đó đúng dịp có khuyến mãi giảm giá nên em làm luôn một thẻ hội viên."}],"readingQuiz":[{"q":"杨同乐一会儿要去做什么？","options":["加班","去健身","办会员卡","开车送王一雪回家"],"answerIdx":1,"explanation":"Dương Đồng Nhạc nói \"我一会儿还要去一趟健身房\" (Lát nữa còn đi phòng tập gym tập thể hình)."},{"q":"关于那家健身房，下列哪项正确？","options":["是新开的","非常便宜","离单位比较远","总有打折活动"],"answerIdx":0,"explanation":"Trong bài nêu \"发现单位旁边新开了一家健身房\" (Mới mở ngay cạnh cơ quan)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"在公司，王一雪和杨同乐下班后在聊天儿。","sceneVi":"Tại công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện sau giờ làm.","lines":[{"speaker":"王一雪","hanzi":"同乐，你晚上不吃饭就去健身，不会饿吗？","pinyin":"Tónglè, nǐ wǎnshang bù chīfàn jiù qù jiànshēn, bú huì è ma?","vi":"Đồng Nhạc, tối em không ăn cơm mà đi tập gym luôn, không bị đói à?"},{"speaker":"杨同乐","hanzi":"我带了饼干、酸奶和果汁，一会儿吃完了再去。","pinyin":"Wǒ dài le bǐnggān, suānnǎi hé guǒzhī, yíhuìr chīwán le zài qù.","vi":"Em có mang bánh quy, sữa chua và nước ép trái cây, lát ăn xong rồi đi."},{"speaker":"王一雪","hanzi":"那你为什么不在家附近找健身房？吃完晚饭，休息一下再去，不是更好吗？","pinyin":"Nà nǐ wèishénme bú zài jiā fùjìn zhǎo jiànshēnfáng? Chīwán wǎnfàn, xiūxi yíxià zài qù, bú shì gèng hǎo ma?","vi":"Thế sao em không tìm phòng gym gần nhà? Ăn tối xong nghỉ ngơi một chút rồi đi chẳng phải tốt hơn sao?"},{"speaker":"杨同乐","hanzi":"离我家最近的健身房也要坐两站公交车，一来一回得半个小时，太浪费时间了。","pinyin":"Lí wǒ jiā zuì jìn de jiànshēnfáng yě yào zuò liǎng zhàn gōngjiāochē, yì lái yì huí děi bàn gè xiǎoshí, tài làngfèi shíjiān le.","vi":"Phòng gym gần nhà em nhất cũng phải đi xe buýt hai bến, cả đi lẫn về mất nửa tiếng đồng hồ, lãng phí thời gian quá."},{"speaker":"王一雪","hanzi":"确实。那这家健身房的教练怎么样？","pinyin":"Quèshí. Nà zhè jiā jiànshēnfáng de jiàoliàn zěnmeyàng?","vi":"Đúng thật. Thế huấn luyện viên ở phòng gym này sao?"},{"speaker":"杨同乐","hanzi":"教练很热情，也非常专业，动作讲得很清楚。","pinyin":"Jiàoliàn hěn rèqíng, yě fēicháng zhuānyè, dòngzuò jiǎng de hěn qīngchu.","vi":"Huấn luyện viên rất nhiệt tình và vô cùng chuyên nghiệp, giảng động tác rất rõ ràng."},{"speaker":"王一雪","hanzi":"听你这么一说，我也想试试了。我现在都是在家看着视频练，动作不一定标准。","pinyin":"Tīng nǐ zhème yì shuō, wǒ yě xiǎng shìshi le. Wǒ xiànzài dōu shì zài jiā kànzhe shìpín liàn, dòngzuò bù yídìng biāozhǔn.","vi":"Nghe em nói vậy chị cũng muốn thử rồi đấy. Giờ chị toàn ở nhà xem video tập theo, động tác chưa chắc đã chuẩn."},{"speaker":"杨同乐","hanzi":"好啊，那您也来吧。锻炼要科学，否则容易受伤。","pinyin":"Hǎo a, nà nín yě lái ba. Duànliàn yào kēxué, fǒuzé róngyì shòushāng.","vi":"Hay quá, vậy chị cũng đến đi ạ. Tập luyện cần khoa học, nếu không rất dễ bị chấn thương."}],"readingQuiz":[{"q":"杨同乐为什么不去家附近的健身房？","options":["太贵了","没有教练","环境不好","要花不少时间"],"answerIdx":3,"explanation":"Dương Đồng Nhạc giải thích \"一来一回得半个小时，太浪费时间了。\" (Đi lại mất nhiều thời gian quá)."},{"q":"公司附近那家健身房的教练怎么样？","options":["很专业","力气大","讲得不清楚","动作不标准"],"answerIdx":0,"explanation":"Trong bài nói \"教练很热情，也非常专业，动作讲得很清楚。\" (Huấn luyện viên rất nhiệt tình và chuyên nghiệp)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"杨同乐的健身情况","sceneVi":"Tình hình tập thể hình của Dương Đồng Nhạc","lines":[{"speaker":"Đoạn văn","hanzi":"有人爱在操场跑步，有人喜欢通过打球锻炼身体，还有一部分人愿意去健身房健身，杨同乐就是其中之一。","pinyin":"Yǒurén ài zài cāochǎng pǎobù, yǒurén xǐhuan tōngguò dǎqiú duànliàn shēntǐ, hái yǒu yí bùfen rén yuànyi qù jiànshēnfáng jiànshēn, Yáng Tónglè jiùshì qízhōng zhī yī.","vi":"Có người thích chạy bộ ở sân vận động, có người thích rèn luyện sức khỏe qua đánh bóng, còn có một bộ phận thích đến phòng gym tập thể hình, Dương Đồng Nhạc chính là một trong số đó."},{"speaker":"Đoạn văn","hanzi":"杨同乐认为健身房火起来是因为它有很多好处——环境好、设备全，可以锻炼全身。另外，健身房里一般还有专业教练，能帮助大家把动作做准确，练习的效果也更好。","pinyin":"Yáng Tónglè rènwéi jiànshēnfáng huǒ qǐlái shì yīnwèi tā yǒu hěnduō hǎochù: huánjìng hǎo, shèbèi quán, kěyǐ duànliàn quánshēn. Lìngwài, jiànshēnfáng lǐ yìbān hái yǒu zhuānyè jiàoliàn, néng bāngzhù dàjiā bǎ dòngzuò zuò zhǔnquè, liànxí de xiàoguǒ yě gèng hǎo.","vi":"Dương Đồng Nhạc cho rằng phòng gym trở nên thịnh hành là vì có nhiều lợi ích: không gian tốt, thiết bị đầy đủ, có thể tập toàn thân. Ngoài ra trong phòng tập thường có huấn luyện viên chuyên nghiệp giúp mọi người tập chuẩn động tác, hiệu quả luyện tập cũng tốt hơn."},{"speaker":"Đoạn văn","hanzi":"仅仅经过一个月左右的锻炼，杨同乐就感觉自己的身体比以前更健康了。教练也表扬他取得了很大的进步，并鼓励他坚持下去，还说随着身体越来越好，人看起来也会更帅。","pinyin":"Jǐnjǐn jīngguò yígè yuè zuǒyòu de duànliàn, Yáng Tónglè jiù gǎnjué zìjǐ de shēntǐ bǐ yǐqián gèng jiànkāng le. Jiàoliàn yě biǎoyáng tā qǔdé le hěn dà de jìnbù, bìng gǔlì tā jiānchí xiàqù, hái shuō suízhe shēntǐ yuèláiyuè hǎo, rén kàn qǐlái yě huì gèng shuài.","vi":"Chỉ sau khoảng một tháng rèn luyện, Dương Đồng Nhạc đã cảm thấy cơ thể khỏe mạnh hơn trước. Huấn luyện viên cũng khen anh tiến bộ rất nhiều, khích lệ anh kiên trì tiếp tục và bảo cùng với việc sức khỏe ngày càng tốt lên, trông người cũng sẽ đẹp trai hơn."}],"readingQuiz":[{"q":"杨同乐喜欢用什么方式锻炼？","options":["打球","游泳","去操场跑步","去健身房健身"],"answerIdx":3,"explanation":"Đoạn văn nêu \"还有一部分人愿意去健身房健身，杨同乐就是其中之一。\" (Dương Đồng Nhạc thích đến phòng gym tập thể hình)."},{"q":"关于杨同乐，下列哪项正确？","options":["身体更健康了","觉得课程简单","不喜欢他的教练","不想坚持健身了"],"answerIdx":0,"explanation":"Bài viết nêu rõ \"杨同乐就感觉自己的身体比以前更健康了\" (Cảm thấy cơ thể khỏe mạnh hơn trước)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"中国的“国球”","sceneVi":"\"Quốc cầu\" của Trung Quốc","lines":[{"speaker":"Đoạn văn","hanzi":"中国乒乓球队非常有名，常在各项比赛中赢得第一名，被叫作“梦之队”。","pinyin":"Zhōngguó Pīngpāngqiúduì fēicháng yǒumíng, cháng zài gè xiàng bǐsài zhōng yíngdé dì yī míng, bèi jiàozuò \"Mèngzhīduì\".","vi":"Đội tuyển bóng bàn Trung Quốc vô cùng nổi tiếng, thường xuyên giành hạng nhất ở các giải đấu và được gọi là \"Đội tuyển trong mơ\"."},{"speaker":"Đoạn văn","hanzi":"为了不断提高自己的水平，队员们每天都要进行严格的训练。正因为这样，球队才能在比赛中取得更好的成绩，获得更多球迷的喜爱。","pinyin":"Wèile búduàn tígāo zìjǐ de shuǐpíng, duìyuánmen měitiān dōu yào jìnxíng yángé de xùnliàn. Zhèng yīnwèi zhèyàng, qiúduì cái néng zài bǐsài zhōng qǔdé gèng hǎo de chéngjì, huòdé gèng duō qiúmí de xǐ'ài.","vi":"Để không ngừng nâng cao trình độ, các vận động viên ngày nào cũng phải tập luyện nghiêm khắc. Chính vì thế đội tuyển mới có thể giành thành tích tốt hơn trong các giải đấu và nhận được sự yêu mến của đông đảo người hâm mộ."},{"speaker":"Đoạn văn","hanzi":"许多年轻的乒乓球运动员都有一个梦想，那就是进入国家队，参加世界大赛，为球队赢下比赛。","pinyin":"Xǔduō niánqīng de pīngpāngqiú yùndòngyuán dōu yǒu yígè mèngxiǎng, nà jiùshì jìnrù guójiāduì, cānjiā shìjiè dàsài, wèi qiúduì yíngxià bǐsài.","vi":"Nhiều vận động viên bóng bàn trẻ đều mang một ước mơ, đó là vào đội tuyển quốc gia, tham gia giải đấu thế giới và mang về chiến thắng cho đội."},{"speaker":"Đoạn văn","hanzi":"在中国，除了专业运动员，喜欢打乒乓球的普通人也特别多。连一些年龄比较大的老人都坚持打球，年轻人更是把它作为一种日常锻炼的方式。可以说，乒乓球是中国人生活中最常见的运动之一。","pinyin":"Zài Zhōngguó, chúle zhuānyè yùndòngyuán, xǐhuan dǎ pīngpāngqiú de pǔtōngrén yě tèbié duō. Lián yìxiē niánlíng bǐjiào dà de lǎorén dōu jiānchí dǎqiú, niánqīngrén gèng shì bǎ tā zuòwéi yì zhǒng rìcháng duànliàn de fāngshì. Kěyǐ shuō, pīngpāngqiú shì Zhōngguórén shēnghuó zhōng zuì chángjiàn de yùndòng zhī yī.","vi":"Ở Trung Quốc, ngoài vận động viên chuyên nghiệp, người bình thường thích chơi bóng bàn cũng đặc biệt đông. Đến cả một số người lớn tuổi vẫn kiên trì đánh bóng, giới trẻ lại càng coi đó là một hình thức rèn luyện hằng ngày. Có thể nói bóng bàn là một trong những môn thể thao phổ biến nhất trong đời sống người Trung Quốc."}],"readingQuiz":[{"q":"中国乒乓球队为什么被叫作“梦之队”？","options":["队员很多","队员很年轻","经常赢得比赛","训练时间很长"],"answerIdx":2,"explanation":"Câu mở đầu giải thích \"常在各项比赛中赢得第一名，被叫作‘梦之队’。\" (Thường xuyên giành giải nhất các cuộc thi)."},{"q":"关于乒乓球在中国的情况，下列哪项正确？","options":["老人最喜欢打乒乓球","只有运动员打乒乓球","年轻人不喜欢打乒乓球","乒乓球是最常见的运动之一"],"answerIdx":3,"explanation":"Cuối bài kết luận \"乒乓球是中国人生活中最常见的运动之一。\" (Bóng bàn là một trong những môn thể thao phổ biến nhất)."}]}],"hsk4b-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"周末下午，安妮骑共享单车到白家月、陈天中所在的学校，三人在学校咖啡馆聊天儿。","sceneVi":"Chiều cuối tuần, An Ni đạp xe đạp chia sẻ đến trường của Bạch Gia Nguyệt và Trần Thiên Trung, cả ba ngồi trò chuyện tại quán cà phê trong trường.","lines":[{"speaker":"白家月","hanzi":"安妮，我们在这儿呢。","pinyin":"Ānnī, wǒmen zài zhèr ne.","vi":"An Ni, tụi mình ở đây này."},{"speaker":"安妮","hanzi":"天中、家月，你们猜我是怎么过来的？","pinyin":"Tiānzhōng, Jiāyuè, nǐmen cāi wǒ shì zěnme guòlái de?","vi":"Thiên Trung, Gia Nguyệt, hai bạn đoán xem mình tới đây bằng cách nào?"},{"speaker":"白家月","hanzi":"坐公交车吗？","pinyin":"Zuò gōngjiāochē ma?","vi":"Đi xe buýt à?"},{"speaker":"安妮","hanzi":"我先坐的公交车，然后骑共享单车，快到那边那个出口时又推了一小段。","pinyin":"Wǒ xiān zuò de gōngjiāochē, ránhòu qí gòngxiǎng dānchē, kuài dào nàbiān nàge chūkǒu shí yòu tuī le yì xiǎo duàn.","vi":"Trước tiên mình đi xe buýt, sau đó đạp xe đạp chia sẻ, gần đến lối ra đằng kia còn dắt bộ thêm một đoạn ngắn nữa."},{"speaker":"白家月","hanzi":"我看很多人都骑共享单车，我还没骑过呢。","pinyin":"Wǒ kàn hěnduō rén dōu qí gòngxiǎng dānchē, wǒ hái méi qí guo ne.","vi":"Mình thấy nhiều người đi xe đạp chia sẻ lắm mà mình vẫn chưa đi thử lần nào."},{"speaker":"陈天中","hanzi":"我骑过，很方便的。第一次骑的时候，你打开微信，对着共享单车上的二维码扫一下，在App上完成注册就可以了，怎么使用、费用标准什么的App上都有说明。","pinyin":"Wǒ qí guo, hěn fāngbiàn de. Dì yī cì qí de shíhou, nǐ dǎkāi Wēixìn, duìzhe gòngxiǎng dānchē shàng de èrwéimǎ sǎo yíxià, zài App shàng wánchéng zhùcè jiù kěyǐ le, zěnme shǐyòng, fèiyong biāozhǔn shénme de App shàng dōu yǒu shuōmíng.","vi":"Mình đi rồi, tiện lắm. Lần đầu đi, bạn mở WeChat quét mã QR trên xe, đăng ký xong trên ứng dụng là được; cách sử dụng, bảng giá phí thế nào trên ứng dụng đều có hướng dẫn cả."},{"speaker":"白家月","hanzi":"好啊！哪天我出去办事时也试试。","pinyin":"Hǎo a! Nǎtiān wǒ chūqù bànshì shí yě shìshi.","vi":"Hay quá! Hôm nào ra ngoài giải quyết công việc mình cũng đi thử."}],"readingQuiz":[{"q":"安妮是怎么到白家月的学校的？","options":["先骑车后坐地铁","先坐地铁后骑车","先骑车后坐公交车","先坐公交车后骑车"],"answerIdx":3,"explanation":"An Ni kể \"我先坐的公交车，然后骑共享单车\" (Đi xe buýt trước rồi mới đạp xe đạp chia sẻ)."},{"q":"第一次骑共享单车，需要扫码后再在App上：","options":["进行支付","完成注册","查看信息","找回密码"],"answerIdx":1,"explanation":"Trần Thiên Trung hướng dẫn \"在App上完成注册就可以了\" (Hoàn tất đăng ký trên ứng dụng là được)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"安妮和白家月、陈天中在学校咖啡馆继续聊天儿。","sceneVi":"An Ni cùng Bạch Gia Nguyệt và Trần Thiên Trung tiếp tục trò chuyện tại quán cà phê trong trường.","lines":[{"speaker":"安妮","hanzi":"差点儿忘了，我给你们看个短视频。","pinyin":"Chàdiǎnr wàng le, wǒ gěi nǐmen kàn gè duǎn shìpín.","vi":"Suýt thì quên mất, mình cho các bạn xem một video ngắn nhé."},{"speaker":"白家月","hanzi":"啊？你们拍的？真不错！","pinyin":"Á? Nǐmen pāi de? Zhēn búcuò!","vi":"Ơ? Các bạn tự quay à? Hay thật đấy!"},{"speaker":"安妮","hanzi":"对！前段时间老师留了个作业，叫各个小组拍个短视频，介绍中国美食。我们小组讨论后决定，由AI小语演厨师，做出中国各地的著名小吃。拍完后，老师说很不错。","pinyin":"Duì! Qián duàn shíjiān lǎoshī liú le gè zuòyè, jiào gègè xiǎozǔ pāi gè duǎn shìpín, jièshào Zhōngguó měishí. Wǒmen xiǎozǔ tǎolùn hòu juédìng, yóu AI Xiǎoyǔ yǎn chúshī, zuòchū Zhōngguó gèdì de zhùmíng xiǎochī. Pāiwán hòu, lǎoshī shuō hěn búcuò.","vi":"Đúng! Thời gian trước thầy giáo giao bài tập bảo mỗi nhóm quay một video ngắn giới thiệu ẩm thực Trung Quốc. Nhóm mình bàn bạc rồi quyết định để AI Tiểu Ngữ đóng vai đầu bếp chế biến các món ăn vặt nổi tiếng khắp vùng miền Trung Quốc. Quay xong thầy khen hay lắm."},{"speaker":"陈天中","hanzi":"嗯，语言也很幽默！","pinyin":"Ǹg, yǔyán yě hěn yōumò!","vi":"Ừm, lời thoại cũng rất hài hước nữa!"},{"speaker":"安妮","hanzi":"后来这个视频让我同学放到了互联网上，很多人都来点赞。","pinyin":"Hòulái zhège shìpín ràng wǒ tóngxué fàngdào le hùliánwǎng shàng, hěnduō rén dōu lái diǎnzàn.","vi":"Sau đó video này được bạn cùng lớp mình đăng lên mạng internet, rất nhiều người vào bấm thích."},{"speaker":"白家月","hanzi":"看来大家都喜欢这个视频。","pinyin":"Kànlái dàjiā dōu xǐhuan zhège shìpín.","vi":"Xem ra ai cũng thích video này rồi."},{"speaker":"安妮","hanzi":"后边我们打算拍第二个、第三个，让小语带大家到中国各地走一走、看一看。","pinyin":"Hòubian wǒmen dǎsuàn pāi dì èr gè, dì sān gè, ràng Xiǎoyǔ dài dàjiā dào Zhōngguó gèdì zǒu yì zǒu, kàn yí kàn.","vi":"Sau này tụi mình định quay tiếp tập hai, tập ba, để Tiểu Ngữ dẫn mọi người đi thăm thú khắp các vùng miền Trung Quốc."},{"speaker":"陈天中","hanzi":"这样大家就能通过你们的视频了解中国了，我支持你们！","pinyin":"Zhèyàng dàjiā jiù néng tōngguò nǐmen de shìpín liǎojiě Zhōngguó le, wǒ zhīchí nǐmen!","vi":"Như vậy mọi người có thể thông qua video của các bạn mà hiểu thêm về Trung Quốc, mình ủng hộ hết mình!"}],"readingQuiz":[{"q":"老师留的短视频作业是关于什么的？","options":["中国美食","饮料广告","校园生活","著名景点"],"answerIdx":0,"explanation":"An Ni nói rõ \"叫各个小组拍个短视频，介绍中国美食。\" (Quay video ngắn giới thiệu ẩm thực Trung Quốc)."},{"q":"大家觉得安妮他们小组拍的短视频怎么样？","options":["有些无聊","效果一般","非常精彩","让人感动"],"answerIdx":2,"explanation":"Mọi người khen \"真不错\", \"幽默\", nhiều người nhấn thích (tổng kết ở bài 3 là \"非常精彩\")."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"科技正在改变我们的生活","sceneVi":"Công nghệ đang thay đổi cuộc sống của chúng ta","lines":[{"speaker":"Đoạn văn","hanzi":"安妮骑共享单车到了白家月、陈天中的学校，三人从共享单车聊到AI眼镜和3D打印机，从绿色经济聊到上门经济。","pinyin":"Ānnī qí gòngxiǎng dānchē dào le Bái Jiāyuè, Chén Tiānzhōng de xuéxiào, sānrén cóng gòngxiǎng dānchē liáodào AI yǎnjìng hé sān D dǎyìnjī, cóng lǜsè jīngjì liáodào shàngmén jīngjì.","vi":"An Ni đạp xe đạp chia sẻ đến trường của Bạch Gia Nguyệt và Trần Thiên Trung, ba người trò chuyện từ xe đạp chia sẻ sang kính AI và máy in 3D, từ kinh tế xanh sang kinh tế phục vụ tận nhà."},{"speaker":"Đoạn văn","hanzi":"科技到底对世界产生了怎样的影响？他们都认为，科技确实改变了人们的生活。","pinyin":"Kējì dàodǐ duì shìjiè chǎnshēng le zěnyàng de yǐngxiǎng? Tāmen dōu rènwéi, kējì quèshí gǎibiàn le rénmen de shēnghuó.","vi":"Công nghệ rốt cuộc đã tạo ra ảnh hưởng thế nào tới thế giới? Cả ba đều cho rằng công nghệ thực sự đã làm thay đổi cuộc sống con người."},{"speaker":"Đoạn văn","hanzi":"接着，安妮给大家看了她和同学们拍的短视频。安妮说，短视频是用手机拍的，他们装了一些免费的App，仅用几天就拍完了。","pinyin":"Jiēzhe, Ānnī gěi dàjiā kàn le tā hé tóngxuémen pāi de duǎn shìpín. Ānnī shuō, duǎn shìpín shì yòng shǒujī pāi de, tāmen zhuāng le yìxiē miǎnfèi de App, jǐn yòng jǐ tiān jiù pāiwán le.","vi":"Tiếp đó An Ni cho mọi người xem video ngắn cô và bạn học quay. An Ni kể video quay bằng điện thoại, họ cài mấy ứng dụng miễn phí, chỉ mất vài ngày đã quay xong."},{"speaker":"Đoạn văn","hanzi":"视频里，小语做的小吃丰富多样，看起来好吃极了。短视频推出后，大家认为非常精彩，白家月和陈天中看后也特别喜欢，并且表示支持他们拍更多的视频。","pinyin":"Shìpín lǐ, Xiǎoyǔ zuò de xiǎochī fēngfù duōyàng, kàn qǐlái hǎochī jíle. Duǎn shìpín tuīchū hòu, dàjiā rènwéi fēicháng jīngcǎi, Bái Jiāyuè hé Chén Tiānzhōng kànhòu yě tèbié xǐhuan, bìngqiě biǎoshì zhīchí tāmen pāi gèng duō de shìpín.","vi":"Trong video, các món ăn vặt Tiểu Ngữ nấu vô cùng phong phú đa dạng, trông ngon hết sẩy. Sau khi ra mắt, mọi người đều thấy rất đặc sắc; Bạch Gia Nguyệt và Trần Thiên Trung xem xong cũng rất thích và bày tỏ sự ủng hộ để họ quay thêm nhiều video nữa."}],"readingQuiz":[{"q":"安妮和朋友们怎么看科技的发展？","options":["科技发展很快","科技不影响世界","科技改变了人们的生活","科技能帮人减轻工作压力"],"answerIdx":2,"explanation":"Đoạn văn viết \"他们都认为，科技确实改变了人们的生活。\" (Công nghệ quả thực đã thay đổi cuộc sống con người)."},{"q":"安妮他们的短视频是用什么拍的？","options":["相机","手机","电脑","电视"],"answerIdx":1,"explanation":"An Ni nói rõ \"短视频是用手机拍的\" (Video ngắn được quay bằng điện thoại)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"当代新经济——上门经济","sceneVi":"Kinh tế mới đương đại — Kinh tế phục vụ tận nhà","lines":[{"speaker":"Đoạn văn","hanzi":"随着互联网技术的发展，现在又出现了一种新的服务方式——上门经济，就是预约者通过网上预约，让服务人员在合适的时间到家里或者约好的地点服务，服务内容有上门做饭、照顾小动物、取东西等。","pinyin":"Suízhe hùliánwǎng jìshù de fāzhǎn, xiànzài yòu chūxiàn le yì zhǒng xīn de fúwù fāngshì, shàngmén jīngjì, jiùshì yùyuēzhě tōngguò wǎngshàng yùyuē, ràng fúwù rényuán zài héshì de shíjiān dào jiālǐ huòzhě yuēhǎo de dìdiǎn fúwù, fúwù nèiróng yǒu shàngmén zuòfàn, zhàogù xiǎo dòngwù, qǔ dōngxi děng.","vi":"Cùng với sự phát triển của công nghệ internet, hiện nay lại xuất hiện một hình thức dịch vụ mới là kinh tế tận nhà: người đặt hẹn đặt lịch qua mạng để nhân viên phục vụ đến tận nhà hoặc địa điểm hẹn vào giờ phù hợp làm các việc như nấu ăn, chăm sóc thú cưng, lấy đồ..."},{"speaker":"Đoạn văn","hanzi":"赵女士养了一只猫，由于工作等原因，她需要经常出差，然而又很担心猫的安全。有了上门服务后，她觉得方便多了，不必再找亲戚帮忙。","pinyin":"Zhào nǚshì yǎng le yì zhī māo, yóuyú gōngzuò děng yuányīn, tā xūyào jīngcháng chūchāi, rán'ér yòu hěn dānxīn māo de ānquán. Yǒu le shàngmén fúwù hòu, tā juéde fāngbiàn duō le, búbì zài zhǎo qīnqi bāngmáng.","vi":"Chị Triệu nuôi một chú mèo, do lý do công việc nên chị thường xuyên phải đi công tác, nhưng lại rất lo lắng cho sự an toàn của mèo. Từ khi có dịch vụ tận nhà, chị thấy tiện hơn nhiều, không còn phải nhờ họ hàng giúp nữa."},{"speaker":"Đoạn văn","hanzi":"每次出差，在网上预约并支付费用后，服务人员就会按她提出的要求上门照顾小猫，大大减轻了她的压力，赵女士也特别满意。","pinyin":"Měi cì chūchāi, zài wǎngshàng yùyuē bìng zhīfù fèiyong hòu, fúwù rényuán jiù huì àn tā tíchū de yāoqiú shàngmén zhàogù xiǎomāo, dàdà jiǎnqīng le tā de yālì, Zhào nǚshì yě tèbié mǎnyì.","vi":"Mỗi lần đi công tác, sau khi đặt lịch và thanh toán phí trực tuyến, nhân viên sẽ tới tận nhà chăm mèo theo đúng yêu cầu chị đưa ra, giúp giảm bớt áp lực rất lớn và chị Triệu vô cùng hài lòng."},{"speaker":"Đoạn văn","hanzi":"当然，上门经济也有一些问题，特别是现有服务人员有些还不够专业，需要重新学习，提高服务质量。","pinyin":"Dāngrán, shàngmén jīngjì yě yǒu yìxiē wèntí, tèbié shì xiànyǒu fúwù rényuán yǒuxiē hái bú gòu zhuānyè, xūyào chóngxīn xuéxí, tígāo fúwù zhìliàng.","vi":"Tất nhiên kinh tế tận nhà cũng có một số vấn đề, đặc biệt là một bộ phận nhân viên hiện nay vẫn chưa đủ chuyên nghiệp, cần được đào tạo lại để nâng cao chất lượng dịch vụ."}],"readingQuiz":[{"q":"根据课文，上门服务怎么预约？","options":["直接打电话","在网上预约","在线下预约","让服务员预约"],"answerIdx":1,"explanation":"Bài viết nêu rõ \"通过网上预约，让服务人员在合适的时间到家里或者约好的地点服务\" (Đặt lịch qua mạng)."},{"q":"赵女士觉得上门服务怎么样？","options":["很方便","难预约","价格低","不安全"],"answerIdx":0,"explanation":"Trong bài viết \"有了上门服务后，她觉得方便多了... 赵女士也特别满意\" (Thấy tiện hơn rất nhiều và rất hài lòng)."}]}],"hsk4b-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"在家里，王一雪和刘小雪谈小雪学校艺术节节目排练情况。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Tiểu Tuyết nói chuyện về tình hình tập luyện tiết mục cho lễ hội nghệ thuật của trường Tiểu Tuyết.","lines":[{"speaker":"王一雪","hanzi":"小雪，你们的话剧排好了吗？","pinyin":"Xiǎoxuě, nǐmen de huàjù páihǎo le ma?","vi":"Tiểu Tuyết, vở kịch nói của các con tập xong chưa?"},{"speaker":"刘小雪","hanzi":"差不多了，妈妈。艺术节周五下午开始，我内心还是有些紧张，有时候不是忘词，就是忘记做动作。","pinyin":"Chàbuduō le, māma. Yìshùjié Zhōuwǔ xiàwǔ kāishǐ, wǒ nèixīn háishi yǒuxiē jǐnzhāng, yǒu shíhou bú shì wàng cí, jiùshì wàngjì zuò dòngzuò.","vi":"Sắp xong rồi ạ, mẹ. Lễ hội nghệ thuật bắt đầu chiều thứ Sáu, trong lòng con vẫn hơi hồi hộp, thỉnh thoảng không quên lời thoại thì lại quên động tác."},{"speaker":"王一雪","hanzi":"没事，妈妈相信你一定可以。放松些，再自信些！","pinyin":"Méishì, māma xiāngxìn nǐ yídìng kěyǐ. Fàngsōng xiē, zài zìxìn xiē!","vi":"Không sao đâu, mẹ tin con nhất định làm được. Thả lỏng chút, tự tin thêm chút nữa nhé!"},{"speaker":"刘小雪","hanzi":"好的，我同学演少年歌手，他的歌声美极了。我演他的妈妈，不知道像不像呢。","pinyin":"Hǎo de, wǒ tóngxué yǎn shàonián gēshǒu, tā de gēshēng měi jíle. Wǒ yǎn tā de māma, bù zhīdào xiàng bù xiàng ne.","vi":"Vâng ạ, bạn học của con đóng vai ca sĩ thiếu niên, giọng hát bạn ấy hay cực kỳ. Con đóng vai mẹ cậu ấy, không biết có giống không nữa."},{"speaker":"王一雪","hanzi":"没问题的，努力做最好的自己就好。演出时，我和你爸都去给你加油。","pinyin":"Méi wèntí de, nǔlì zuò zuì hǎo de zìjǐ jiù hǎo. Yǎnchū shí, wǒ hé nǐ bà dōu qù gěi nǐ jiāyóu.","vi":"Không vấn đề gì đâu, chỉ cần cố gắng thể hiện bản thân tốt nhất là được. Lúc biểu diễn mẹ và bố đều sẽ đến cổ vũ cho con."},{"speaker":"刘小雪","hanzi":"好的，谢谢妈妈！","pinyin":"Hǎo de, xièxie māma!","vi":"Vâng ạ, con cảm ơn mẹ!"}],"readingQuiz":[{"q":"小雪和同学们的话剧排得怎么样了？","options":["排好了","还差很多","还没开始排","基本上排好了"],"answerIdx":3,"explanation":"Tiểu Tuyết trả lời \"差不多了\" (Cơ bản đã tập xong xuôi rồi)."},{"q":"小雪的同学唱歌怎么样？","options":["很爱忘词","比较一般","很有感情","特别好听"],"answerIdx":3,"explanation":"Tiểu Tuyết khen \"他的歌声美极了\" (Giọng hát bạn ấy hay tuyệt vời)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"周六，李文和白家月、安妮、陈天中视频通话。","sceneVi":"Thứ Bảy, Lý Văn gọi video trò chuyện cùng Bạch Gia Nguyệt, An Ni và Trần Thiên Trung.","lines":[{"speaker":"李文","hanzi":"下周六晚上，我请大家去国家大剧院看京剧，怎么样？","pinyin":"Xià Zhōuliù wǎnshang, wǒ qǐng dàjiā qù Guójiā Dàjùyuàn kàn Jīngjù, zěnmeyàng?","vi":"Tối thứ Bảy tuần sau mình mời mọi người đến Nhà hát Lớn Quốc gia xem Kinh kịch, thấy sao nào?"},{"speaker":"安妮","hanzi":"好啊。我小时候在加拿大度假时，在宾馆的电视上看过一次，是梅兰芳等演员演的，演员们都非常棒，他们演唱得好听极了，给我留下的印象特别深。","pinyin":"Hǎo a. Wǒ xiǎoshíhou zài Jiānádà dùjià shí, zài bīnguǎn de diànshì shàng kàn guo yí cì, shì Méi Lánfāng děng yǎnyuán yǎn de, yǎnyuánmen dōu fēicháng bàng, tāmen yǎnchàng de hǎotīng jíle, gěi wǒ liúxià de yìnxiàng tèbié shēn.","vi":"Hay quá! Hồi nhỏ lúc nghỉ mát ở Canada mình từng xem trên tivi khách sạn một lần, do các nghệ sĩ như Mai Lan Phương biểu diễn, các diễn viên đều rất xuất sắc, hát cực kỳ hay, để lại ấn tượng sâu sắc cho mình."},{"speaker":"李文","hanzi":"梅兰芳先生是中国著名京剧艺术家。咱们要看的这个京剧是青年演员们演的，要去看的观众也特别多。","pinyin":"Méi Lánfāng xiānsheng shì Zhōngguó zhùmíng Jīngjù yìshùjiā. Zánmen yào kàn de zhège Jīngjù shì qīngnián yǎnyuánmen yǎn de, yào qù kàn de guānzhòng yě tèbié duō.","vi":"Tiên sinh Mai Lan Phương là nghệ sĩ Kinh kịch nổi tiếng của Trung Quốc. Vở Kinh kịch tụi mình sắp xem do các diễn viên trẻ biểu diễn, khán giả đi xem cũng rất đông."},{"speaker":"陈天中","hanzi":"不知道我们能不能看懂。","pinyin":"Bù zhīdào wǒmen néng bù néng kàndǒng.","vi":"Không biết tụi mình có xem hiểu được không nhỉ."},{"speaker":"白家月","hanzi":"咱们先做做功课，提前了解下，能懂一点儿是一点儿。","pinyin":"Zánmen xiān zuòzuo gōngkè, tíqián liǎojiě xià, néng dǒng yìdiǎnr shì yìdiǎnr.","vi":"Tụi mình tìm hiểu bài trước đi, nắm sơ trước một chút, hiểu được chút nào hay chút nấy."},{"speaker":"陈天中","hanzi":"对，我先去网上查资料，查完后也转发给你们。","pinyin":"Duì, wǒ xiān qù wǎngshàng chá zīliào, cháwán hòu yě zhuǎnfā gěi nǐmen.","vi":"Đúng đấy, để mình lên mạng tra tài liệu trước, tra xong rồi chuyển tiếp cho mọi người."},{"speaker":"安妮","hanzi":"谢谢天中！","pinyin":"Xièxie Tiānzhōng!","vi":"Cảm ơn Thiên Trung!"},{"speaker":"李文","hanzi":"那我就在网上订票了，到时候咱们在大剧院入口见。","pinyin":"Nà wǒ jiù zài wǎngshàng dìngpiào le, dào shíhou zánmen zài Dàjùyuàn rùkǒu jiàn.","vi":"Vậy mình đặt vé trên mạng nhé, đến lúc đó gặp nhau ở cổng vào Nhà hát Lớn."}],"readingQuiz":[{"q":"下周六晚上，李文请大家去做什么？","options":["散步","聚餐","看电影","看京剧"],"answerIdx":3,"explanation":"Lý Văn mời \"去国家大剧院看京剧\" (Đi Nhà hát Lớn Quốc gia xem Kinh kịch)."},{"q":"白家月说的“做功课”最可能是什么意思？","options":["提前了解","完成作业","翻译内容","学唱京剧"],"answerIdx":0,"explanation":"Ngay sau \"做做功课\" Bạch Gia Nguyệt nói \"提前了解下\" (Tìm hiểu trước một chút)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"精彩的演出","sceneVi":"Buổi biểu diễn đặc sắc","lines":[{"speaker":"Đoạn văn","hanzi":"周六晚上，李文等四人来到国家大剧院观看京剧演出。入座后，李文指着节目表说：“这些演员很专业，功夫很深，在京剧比赛中获过很多奖，有的还是国家、国际大奖。我特别期待这场演出。”","pinyin":"Zhōuliù wǎnshang, Lǐ Wén děng sì rén láidào Guójiā Dàjùyuàn guānkàn Jīngjù yǎnchū. Rùzuò hòu, Lǐ Wén zhǐzhe jiémùbiǎo shuō: \"Zhèxiē yǎnyuán hěn zhuānyè, gōngfu hěn shēn, zài Jīngjù bǐsài zhōng huò guo hěnduō jiǎng, yǒude háishi guójiā, guójì dàjiǎng. Wǒ tèbié qīdài zhè chǎng yǎnchū.\"","vi":"Tối thứ Bảy, bốn người Lý Văn đến Nhà hát Lớn Quốc gia xem biểu diễn Kinh kịch. Sau khi ngồi vào chỗ, Lý Văn chỉ vào tờ chương trình nói: \"Các diễn viên này rất chuyên nghiệp, công phu thâm hậu, từng đoạt nhiều giải thưởng trong các cuộc thi Kinh kịch, có người còn đạt giải lớn quốc gia và quốc tế. Mình đặc biệt mong chờ buổi diễn này.\""},{"speaker":"Đoạn văn","hanzi":"演出开始后，他们看到演员们做的动作很难，但是做得都特别好，观众们不断鼓掌。因为李文他们提前把故事了解了一遍，所以差不多都看懂了。","pinyin":"Yǎnchū kāishǐ hòu, tāmen kàndào yǎnyuánmen zuò de dòngzuò hěn nán, dànshì zuò de dōu tèbié hǎo, guānzhòngmen búduàn gǔzhǎng. Yīnwèi Lǐ Wén tāmen tíqián bǎ gùshi liǎojiě le yíbiàn, suǒyǐ chàbuduō dōu kàndǒng le.","vi":"Sau khi buổi diễn bắt đầu, họ thấy các động tác diễn viên thực hiện rất khó nhưng làm đều cực kỳ xuất sắc, khán giả vỗ tay không ngớt. Nhờ nhóm Lý Văn đã tìm hiểu trước cốt truyện một lượt nên gần như đều xem hiểu hết."},{"speaker":"Đoạn văn","hanzi":"演出结束后，演员们邀请观众和他们一起庆祝演出成功。回来的路上，大家特别激动，觉得京剧很有意思，演员演得很精彩。李文点头说：“是啊，以后咱们还来看。”","pinyin":"Yǎnchū jiéshù hòu, yǎnyuánmen yāoqǐng guānzhòng hé tāmen yìqǐ qìngzhù yǎnchū chénggōng. Huílái de lùshàng, dàjiā tèbié jīdòng, juéde Jīngjù hěn yǒuyìsi, yǎnyuán yǎn de hěn jīngcǎi. Lǐ Wén diǎntóu shuō: \"Shì a, yǐhòu zánmen hái lái kàn.\"","vi":"Kết thúc buổi diễn, các diễn viên mời khán giả cùng chung vui chúc mừng buổi diễn thành công. Trên đường về mọi người vô cùng phấn khích, thấy Kinh kịch thật thú vị và diễn viên diễn rất xuất sắc. Lý Văn gật đầu bảo: \"Đúng vậy, sau này tụi mình lại tới xem nữa.\""}],"readingQuiz":[{"q":"李文很期待那场演出，因为：","options":["演员很专业","故事有意思","音乐很好听","内容很幽默"],"answerIdx":0,"explanation":"Lý Văn giới thiệu \"这些演员很专业，功夫很深，在京剧比赛中获过很多奖... 我特别期待这场演出。\" (Các diễn viên rất chuyên nghiệp)."},{"q":"演出结束后，演员们邀请观众一起做什么？","options":["回答问题","学京剧动作","继续演节目","庆祝演出成功"],"answerIdx":3,"explanation":"Đoạn văn nêu rõ \"演员们邀请观众和他们一起庆祝演出成功。\" (Mời khán giả cùng ăn mừng buổi diễn thành công)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"白家月的日记","sceneVi":"Nhật ký của Bạch Gia Nguyệt","lines":[{"speaker":"Đoạn văn","hanzi":"马可·波罗是意大利旅行家，在1275年和家人来到中国，在中国大约生活了17年，最后完成了一部作品《马可·波罗游记》。在这部影响很大的作品中，作者向世界介绍了13世纪时的中国。","pinyin":"Mǎkě Bōluó shì Yìdàlì lǚxíngjiā, zài yī èr qī wǔ nián hé jiārén láidào Zhōngguó, zài Zhōngguó dàyuē shēnghuó le shíqī nián, zuìhòu wánchéng le yí bù zuòpǐn Mǎkě Bōluó Yóujì. Zài zhè bù yǐngxiǎng hěn dà de zuòpǐn zhōng, zuòzhě xiàng shìjiè jièshào le shísān shìjì shí de Zhōngguó.","vi":"Marco Polo là nhà du hành người Ý, năm 1275 ông cùng gia đình đến Trung Quốc, sống ở Trung Quốc khoảng 17 năm rồi hoàn thành tác phẩm \"Marco Polo du ký\". Trong tác phẩm có tầm ảnh hưởng lớn này, tác giả đã giới thiệu Trung Quốc thế kỷ 13 ra toàn thế giới."},{"speaker":"Đoạn văn","hanzi":"作为读者，读完这部作品后，我也很想成为作家，更想来中国看看。来到中国后，我发现现在的中国和书里的中国已有很大不同。","pinyin":"Zuòwéi dúzhě, dúwán zhè bù zuòpǐn hòu, wǒ yě hěn xiǎng chéngwéi zuòjiā, gèng xiǎng lái Zhōngguó kànkan. Láidào Zhōngguó hòu, wǒ fāxiàn xiànzài de Zhōngguó hé shūlǐ de Zhōngguó yǐ yǒu hěn dà bùtóng.","vi":"Là một độc giả, sau khi đọc xong tác phẩm này tôi cũng rất muốn trở thành nhà văn và càng muốn tới Trung Quốc thăm thú. Sau khi sang Trung Quốc, tôi phát hiện Trung Quốc hiện nay đã khác rất nhiều so với Trung Quốc trong sách."},{"speaker":"Đoạn văn","hanzi":"前两天，我去书店看到了中文版的《马可·波罗游记》，马上买了一本，到家后又把这本书看了两天。","pinyin":"Qián liǎng tiān, wǒ qù shūdiàn kàndào le Zhōngwénbǎn de Mǎkě Bōluó Yóujì, mǎshàng mǎi le yì běn, dào jiā hòu yòu bǎ zhè běn shū kàn le liǎng tiān.","vi":"Mấy hôm trước tôi đi hiệu sách thấy bản tiếng Trung của cuốn \"Marco Polo du ký\", liền mua ngay một cuốn, về nhà lại đọc cuốn sách đó suốt hai ngày."},{"speaker":"Đoạn văn","hanzi":"看完后，我决定把自己来中国后写的文章、日记等全部整理出来，完成一部文字加图片的作品《东方旅行日记》，再次把中国介绍给世界。同时我也想继续学习中文和中国文化，报考中国语言文学专业的研究生。","pinyin":"Kànwán hòu, wǒ juédìng bǎ zìjǐ lái Zhōngguó hòu xiě de wénzhāng, rìjì děng quánbù zhěnglǐ chūlái, wánchéng yí bù wénzì jiā túpiàn de zuòpǐn Dōngfāng Lǚxíng Rìjì, zàicì bǎ Zhōngguó jièshào gěi shìjiè. Tóngshí wǒ yě xiǎng jìxù xuéxí Zhōngwén hé Zhōngguó wénhuà, bàokǎo Zhōngguó yǔyán wénxué zhuānyè de yánjiūshēng.","vi":"Đọc xong, tôi quyết định tổng hợp toàn bộ bài viết, nhật ký mình viết từ khi sang Trung Quốc, hoàn thành một tác phẩm kết hợp chữ viết và hình ảnh mang tên \"Nhật ký du hành phương Đông\" để một lần nữa giới thiệu Trung Quốc với thế giới. Đồng thời tôi cũng muốn tiếp tục học tiếng Trung và văn hóa Trung Quốc, thi thạc sĩ chuyên ngành Ngôn ngữ và Văn học Trung Quốc."}],"readingQuiz":[{"q":"《马可·波罗游记》介绍了什么内容？","options":["中国的经济","中国的教育","现在的中国","13世纪的中国"],"answerIdx":3,"explanation":"Bài viết nêu rõ \"作者向世界介绍了13世纪时的中国\" (Giới thiệu Trung Quốc ở thế kỷ 13)."},{"q":"白家月看完中文版的《马可·波罗游记》之后打算做什么？","options":["去意大利玩","把它翻译给家人","完成自己的作品","再买一本送给朋友"],"answerIdx":2,"explanation":"Bạch Gia Nguyệt quyết định sắp xếp lại bài viết và nhật ký để \"完成一部文字加图片的作品《东方旅行日记》\" (Hoàn thành tác phẩm của riêng mình)."}]}],"hsk4b-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","scene":"白家月、安妮和陈天中坐动车去杭州、苏州游玩。","sceneVi":"Bạch Gia Nguyệt, An Ni và Trần Thiên Trung đi tàu cao tốc động xa đến Hàng Châu, Tô Châu du ngoạn.","lines":[{"speaker":"安妮","hanzi":"终于上车了，刚刚路上堵车，差点儿晚了。","pinyin":"Zhōngyú shàngchē le, gānggāng lùshàng dǔchē, chàdiǎnr wǎn le.","vi":"Cuối cùng cũng lên tàu rồi, vừa nãy trên đường tắc xe, suýt nữa thì trễ."},{"speaker":"白家月","hanzi":"没关系，晚了就改乘下一趟。天中，你坐哪儿？看你一直不坐下，我还在想，难道你买的是无座票吗？","pinyin":"Méi guānxi, wǎn le jiù gǎichéng xià yí tàng. Tiānzhōng, nǐ zuò nǎr? Kàn nǐ yìzhí bú zuòxià, wǒ hái zài xiǎng, nándào nǐ mǎi de shì wúzuò piào ma?","vi":"Không sao đâu, trễ thì đổi sang chuyến sau. Thiên Trung, bạn ngồi đâu thế? Thấy bạn đứng mãi chẳng ngồi, mình còn đang nghĩ chẳng lẽ bạn mua vé không chỗ ngồi à?"},{"speaker":"陈天中","hanzi":"我的座位就在前边，我想先站这儿跟你们说说话。","pinyin":"Wǒ de zuòwèi jiù zài qiánbian, wǒ xiǎng xiān zhàn zhèr gēn nǐmen shuōshuō huà.","vi":"Ghế của mình ngay phía trước kia, mình muốn đứng đây nói chuyện với các bạn một chút đã."},{"speaker":"安妮","hanzi":"动车车速也挺快啊！对了，这列车晚上七点多到杭州，咱们在车上吃晚餐，到站后就先去西湖吧，夜里的西湖更美。","pinyin":"Dòngchē chēsù yě tǐng kuài a! Duìle, zhè lièchē wǎnshang qī diǎn duō dào Hángzhōu, zánmen zài chēshàng chī wǎncān, dào zhàn hòu jiù xiān qù Xī Hú ba, yèlǐ de Xī Hú gèng měi.","vi":"Tốc độ tàu động xa nhanh thật đấy! À, chuyến tàu này hơn bảy giờ tối tới Hàng Châu, tụi mình ăn tối trên tàu, xuống ga rồi đi Tây Hồ trước nhé, Tây Hồ ban đêm đẹp hơn nữa."},{"speaker":"陈天中","hanzi":"好！后天我们坐大巴去苏州，看苏州园林。","pinyin":"Hǎo! Hòutiān wǒmen zuò dàbā qù Sūzhōu, kàn Sūzhōu Yuánlín.","vi":"Được! Ngày kia tụi mình đi xe buýt đường dài sang Tô Châu, ngắm Lâm viên Tô Châu."},{"speaker":"白家月","hanzi":"嗯。中国太大了！真是看也看不完啊。","pinyin":"Ǹg. Zhōngguó tài dà le! Zhēnshi kàn yě kàn bù wán a.","vi":"Ừ. Trung Quốc rộng lớn quá! Đúng thật là ngắm mãi cũng không hết được."}],"readingQuiz":[{"q":"如果安妮没有坐上车，白家月有什么建议？","options":["明天再去","改坐飞机","坐下一趟车","买张无座票"],"answerIdx":2,"explanation":"Bạch Gia Nguyệt nói \"没关系，晚了就改乘下一趟。\" (Trễ thì đổi sang chuyến tiếp theo)."},{"q":"安妮为什么建议下车后就去西湖？","options":["西湖离得近","去西湖方便","西湖不要门票","晚上西湖更好看"],"answerIdx":3,"explanation":"An Ni nói rõ \"到站后就先去西湖吧，夜里的西湖更美。\" (Tây Hồ ban đêm đẹp hơn)."}]},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","scene":"在机场，李文和白家月、安妮、陈天中安检后准备登机去西双版纳，他们先在西安转机。","sceneVi":"Tại sân bay, sau khi kiểm tra an ninh, Lý Văn cùng Bạch Gia Nguyệt, An Ni và Trần Thiên Trung chuẩn bị lên máy bay đi Tây Song Bản Nạp, trước tiên họ quá cảnh ở Tây An.","lines":[{"speaker":"李文","hanzi":"安检完就等着登机了。你们在看什么？","pinyin":"Ānjiǎn wán jiù děngzhe dēngjī le. Nǐmen zài kàn shénme?","vi":"Qua cửa an ninh rồi thì đợi lên máy bay thôi. Các bạn đang đọc gì thế?"},{"speaker":"白家月","hanzi":"我在读老舍的小说。","pinyin":"Wǒ zài dú Lǎoshě de xiǎoshuō.","vi":"Mình đang đọc tiểu thuyết của Lão Xá."},{"speaker":"陈天中","hanzi":"我读的是一本中国历史书。","pinyin":"Wǒ dú de shì yì běn Zhōngguó lìshǐshū.","vi":"Cuốn mình đọc là một quyển sách lịch sử Trung Quốc."},{"speaker":"安妮","hanzi":"我读唐诗呢。几千年的中国文化，真是读也读不完。","pinyin":"Wǒ dú Tángshī ne. Jǐqiān nián de Zhōngguó wénhuà, zhēnshi dú yě dú bù wán.","vi":"Mình đang đọc thơ Đường. Mấy nghìn năm văn hóa Trung Quốc, đúng là đọc mãi chẳng hết."},{"speaker":"李文","hanzi":"谁说不是呢？不过，现在咱们得去排队，航班的值机员在叫大家登机呢。","pinyin":"Shuí shuō bú shì ne? Búguò, xiànzài zánmen děi qù páiduì, hángbān de zhíjīyuán zài jiào dàjiā dēngjī ne.","vi":"Ai bảo không phải chứ? Nhưng bây giờ tụi mình phải đi xếp hàng rồi, nhân viên quầy thủ tục chuyến bay đang gọi mọi người lên máy bay kìa."},{"speaker":"Dẫn chuyện","hanzi":"（值机员的话）去西安的旅客开始登机，请拿好登机牌按顺序排队。","pinyin":"(Zhíjīyuán de huà) Qù Xī'ān de lǚkè kāishǐ dēngjī, qǐng náhǎo dēngjīpái àn shùnxù páiduì.","vi":"(Lời nhân viên làm thủ tục) Hành khách đi Tây An bắt đầu lên máy bay, xin vui lòng cầm sẵn thẻ lên máy bay và xếp hàng theo thứ tự."},{"speaker":"白家月","hanzi":"终于上来了，我的座位靠窗户。","pinyin":"Zhōngyú shànglái le, wǒ de zuòwèi kào chuānghu.","vi":"Cuối cùng cũng lên được máy bay rồi, chỗ ngồi của mình sát cửa sổ."},{"speaker":"安妮","hanzi":"我在最外边。这么多人，是不是跟咱们一样，都是去感受泼水节的啊？","pinyin":"Wǒ zài zuì wàibian. Zhème duō rén, shìbushì gēn zánmen yíyàng, dōu shì qù gǎnshòu Pōshuǐjié de a?","vi":"Mình ngồi ngoài cùng. Đông người thế này, có phải đều giống tụi mình đi trải nghiệm Lễ hội Té nước không nhỉ?"},{"speaker":"李文","hanzi":"应该不是。很多人的目的地是西安，你别忘了，咱们是在西安转机，然后再飞西双版纳。","pinyin":"Yīnggāi bú shì. Hěnduō rén de mùdìdì shì Xī'ān, nǐ bié wàng le, zánmen shì zài Xī'ān zhuǎnjī, ránhòu zài fēi Xīshuāngbǎnnà.","vi":"Chắc không phải đâu. Điểm đến của nhiều người là Tây An, bạn đừng quên tụi mình quá cảnh ở Tây An rồi mới bay tiếp đi Tây Song Bản Nạp."}],"readingQuiz":[{"q":"安检完后，白家月、陈天中和安妮都在干什么？","options":["看书","买东西","看电影","听中文歌"],"answerIdx":0,"explanation":"Gia Nguyệt đọc tiểu thuyết Lão Xá, Thiên Trung đọc sách lịch sử, An Ni đọc thơ Đường — cả ba đều đang đọc sách."},{"q":"他们这次去西双版纳要做什么？","options":["吃美食","听演唱会","参加比赛","感受泼水节"],"answerIdx":3,"explanation":"An Ni nói \"是不是跟咱们一样，都是去感受泼水节的啊？\" (Cùng đi trải nghiệm Lễ hội Té nước ở Tây Song Bản Nạp)."}]},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","scene":"旅行经验谈","sceneVi":"Chia sẻ kinh nghiệm du lịch","lines":[{"speaker":"Đoạn văn","hanzi":"来中国留学后，白家月、安妮和陈天中常外出旅行，从中了解中国。他们还总结出几点旅行经验：","pinyin":"Lái Zhōngguó liúxué hòu, Bái Jiāyuè, Ānnī hé Chén Tiānzhōng cháng wàichū lǚxíng, cóngzhōng liǎojiě Zhōngguó. Tāmen hái zǒngjié chū jǐ diǎn lǚxíng jīngyàn:","vi":"Sau khi đến Trung Quốc du học, Bạch Gia Nguyệt, An Ni và Trần Thiên Trung thường đi du lịch để từ đó tìm hiểu về Trung Quốc. Họ còn đúc kết được mấy kinh nghiệm du lịch:"},{"speaker":"Đoạn văn","hanzi":"第一，好计划是成功的一半。旅行前，要了解目的地天气、道路交通特点等，安排好每天的活动，保证所有人对计划都没意见。准备越细，烦恼越少。","pinyin":"Dì yī, hǎo jìhuà shì chénggōng de yíbàn. Lǚxíng qián, yào liǎojiě mùdìdì tiānqì, dàolù jiāotōng tèdiǎn děng, ānpái hǎo měitiān de huódòng, bǎozhèng suǒyǒu rén duì jìhuà dōu méi yìjiàn. Zhǔnbèi yuè xì, fánnǎo yuè shǎo.","vi":"Thứ nhất, kế hoạch tốt là thành công một nửa. Trước khi đi cần tìm hiểu thời tiết điểm đến, đặc điểm giao thông đường sá..., sắp xếp ổn thỏa hoạt động từng ngày để mọi người đều đồng thuận. Chuẩn bị càng kỹ thì phiền muộn càng ít."},{"speaker":"Đoạn văn","hanzi":"第二，节假日早点儿订机票、酒店和各种门票，否则很难订到。","pinyin":"Dì èr, jiéjiàrì zǎodiǎnr dìng jīpiào, jiǔdiàn hé gèzhǒng ménpiào, fǒuzé hěn nán dìngdào.","vi":"Thứ hai, dịp lễ Tết nên đặt vé máy bay, khách sạn và các loại vé tham quan sớm một chút, nếu không rất khó đặt được."},{"speaker":"Đoạn văn","hanzi":"第三，转机会比直飞更便宜。此次去西双版纳，在西安转机，机票价格比直飞便宜了百分之四十多。虽然有些累，但累就累点儿吧，花更少的钱去看更多的地方，很值得，节省下来的钱就当是给自己的大“红包”了。","pinyin":"Dì sān, zhuǎnjī huì bǐ zhífēi gèng piányi. Cǐcì qù Xīshuāngbǎnnà, zài Xī'ān zhuǎnjī, jīpiào jiàgé bǐ zhífēi piányi le bǎi fēn zhī sìshí duō. Suīrán yǒuxiē lèi, dàn lèi jiù lèi diǎnr ba, huā gèng shǎo de qián qù kàn gèng duō de dìfang, hěn zhídé, jiéshěng xiàlái de qián jiù dāng shì gěi zìjǐ de dà \"hóngbāo\" le.","vi":"Thứ ba, bay nối chuyến sẽ rẻ hơn bay thẳng. Lần này đi Tây Song Bản Nạp quá cảnh tại Tây An, giá vé máy bay rẻ hơn bay thẳng tới hơn 40%. Tuy hơi mệt nhưng mệt chút cũng được, tốn ít tiền hơn để đi ngắm nhiều nơi hơn thì rất đáng, số tiền tiết kiệm được coi như một phong bao lì xì lớn tự thưởng cho mình."}],"readingQuiz":[{"q":"白家月、安妮和陈天中想通过旅行：","options":["放松心情","交到朋友","了解中国","积累知识"],"answerIdx":2,"explanation":"Câu đầu nêu rõ \"常外出旅行，从中了解中国\" (Thường đi du lịch để từ đó tìm hiểu về Trung Quốc)."},{"q":"白家月、安妮和陈天中的旅行经验首先是：","options":["提前订好酒店","做好旅行计划","提前订好门票","仔细检查行李"],"answerIdx":1,"explanation":"Kinh nghiệm thứ nhất viết \"第一，好计划是成功的一半\" (Lên kế hoạch du lịch thật tốt)."}]},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","scene":"读万卷书，行万里路","sceneVi":"Đọc vạn quyển sách, đi vạn dặm đường","lines":[{"speaker":"Đoạn văn","hanzi":"王一飞常对她的学生说：“读万卷书，行万里路。你们要是想多了解中国，就不能只通过读书，还要多出门旅行，否则只能认识课本里的中国。”","pinyin":"Wáng Yīfēi cháng duì tā de xuésheng shuō: \"Dú wàn juàn shū, xíng wàn lǐ lù. Nǐmen yàoshi xiǎng duō liǎojiě Zhōngguó, jiù bùnéng zhǐ tōngguò dúshū, hái yào duō chūmén lǚxíng, fǒuzé zhǐnéng rènshi kèběn lǐ de Zhōngguó.\"","vi":"Vương Nhất Phi thường nói với học trò của mình: \"Đọc vạn quyển sách, đi vạn dặm đường. Nếu các em muốn hiểu nhiều hơn về Trung Quốc thì không thể chỉ đọc sách, mà còn phải ra ngoài du lịch nhiều hơn, nếu không chỉ biết được Trung Quốc qua trang sách thôi.\""},{"speaker":"Đoạn văn","hanzi":"旅行，不仅能看到自然美景，还能近距离感受不同的历史文化。比如，白家月等人想了解少数民族泼水节，就去了西双版纳。泼水节上，导游向他们解释说，被泼的水越多，新的一年就会越健康、幸福。","pinyin":"Lǚxíng, bùjǐn néng kàndào zìrán měijǐng, hái néng jìn jùlí gǎnshòu bùtóng de lìshǐ wénhuà. Bǐrú, Bái Jiāyuè děng rén xiǎng liǎojiě shǎoshù mínzú Pōshuǐjié, jiù qù le Xīshuāngbǎnnà. Pōshuǐjié shàng, dǎoyóu xiàng tāmen jiěshì shuō, bèi pō de shuǐ yuè duō, xīn de yì nián jiù huì yuè jiànkāng, xìngfú.","vi":"Du lịch không chỉ giúp ngắm cảnh đẹp thiên nhiên mà còn trực tiếp cảm nhận lịch sử văn hóa đa dạng. Ví dụ nhóm Bạch Gia Nguyệt muốn tìm hiểu Lễ hội Té nước của dân tộc thiểu số nên đã tới Tây Song Bản Nạp. Tại lễ hội, hướng dẫn viên giải thích rằng người được té càng nhiều nước thì năm mới sẽ càng khỏe mạnh, hạnh phúc."},{"speaker":"Đoạn văn","hanzi":"安妮喜欢唐诗，就来到了西安，在那里遇到身穿唐装的“对诗人”，对诗人说上句，游客就能流利地说出下句。安妮觉得在西安，唐诗活了。","pinyin":"Ānnī xǐhuan Tángshī, jiù láidào le Xī'ān, zài nàlǐ yùdào shēnchuān Tángzhuāng de \"duìshīrén\", duìshīrén shuō shàngjù, yóukè jiù néng liúlì de shuōchū xiàjù. Ānnī juéde zài Xī'ān, Tángshī huó le.","vi":"An Ni thích thơ Đường nên đến Tây An, tại đó gặp những người đối thơ mặc trang phục nhà Đường; người đối thơ đọc câu trên, du khách có thể đọc lưu loát câu dưới. An Ni cảm thấy ở Tây An thơ Đường như sống dậy vậy."},{"speaker":"Đoạn văn","hanzi":"虽然已经去了很多地方，但是白家月他们觉得还不够。他们也认为，美丽中国，不只是在书中，更是在脚下。","pinyin":"Suīrán yǐjīng qù le hěnduō dìfang, dànshì Bái Jiāyuè tāmen juéde hái bú gòu. Tāmen yě rènwéi, měilì Zhōngguó, bù zhǐ shì zài shū zhōng, gèng shì zài jiǎoxià.","vi":"Tuy đã đi qua nhiều nơi nhưng nhóm Bạch Gia Nguyệt vẫn thấy chưa đủ. Họ cũng tin rằng Trung Quốc tươi đẹp không chỉ nằm trong sách vở mà còn ở ngay dưới mỗi bước chân đi."}],"readingQuiz":[{"q":"“读万卷书，行万里路”的意思是：","options":["既学习也运动","边看书边走路","读一万本书，走一万里路","既读书学习，也外出看世界"],"answerIdx":3,"explanation":"Vương Nhất Phi giải thích không thể chỉ đọc sách mà phải ra ngoài đi du lịch, tức là vừa học qua sách vở vừa trải nghiệm thế giới thực tế."},{"q":"根据课文，旅行除了能看自然景色外，还能：","options":["吃美食","认识朋友","了解历史文化","了解旅行过程"],"answerIdx":2,"explanation":"Trong bài nêu rõ \"旅行，不仅能看到自然美景，还能近距离感受不同的历史文化。\" (Cảm nhận lịch sử văn hóa ở cự ly gần)."}]}]});
